-- Frozen empty Ready schema from Git commit f175a25f9b573ca97bfb2788d1208a144aba46f0.

-- Generated by the unmodified historical runMigrations through 115; do not rebuild with live migrations.

-- Includes schema, the real ledger, and only system defaults produced in that historical empty database.

-- No user data, local user paths, or credentials; the default workspace root is the literal @shared.

-- Virtual shadow tables are omitted because their parent virtual tables create them.

PRAGMA foreign_keys = OFF;

CREATE TABLE migrations (
      id INTEGER PRIMARY KEY,
      name TEXT NOT NULL UNIQUE,
      applied_at TEXT NOT NULL
    );

CREATE TABLE rss_sources (
          id TEXT PRIMARY KEY,
          name TEXT NOT NULL,
          url TEXT NOT NULL UNIQUE,
          group_name TEXT DEFAULT 'default',
          icon TEXT,
          last_fetched INTEGER,
          fetch_interval INTEGER DEFAULT 30,
          enabled INTEGER DEFAULT 1,
          created_at INTEGER DEFAULT (unixepoch())
        , platform TEXT DEFAULT 'rss', draft_seeded INTEGER DEFAULT 0);

CREATE TABLE rss_items (
          id TEXT PRIMARY KEY,
          source_id TEXT NOT NULL,
          guid TEXT NOT NULL UNIQUE,
          title TEXT NOT NULL,
          link TEXT NOT NULL,
          summary TEXT,
          cover_image TEXT,
          author TEXT,
          published_at INTEGER,
          fetched_at INTEGER DEFAULT (unixepoch()),
          read INTEGER DEFAULT 0,
          starred INTEGER DEFAULT 0,
          ai_score INTEGER,
          ai_tags TEXT, inbox_visible INTEGER DEFAULT 1,
          FOREIGN KEY (source_id) REFERENCES rss_sources(id) ON DELETE CASCADE
        );

CREATE TABLE calendar_sources (
          id TEXT PRIMARY KEY,
          name TEXT NOT NULL,
          color TEXT NOT NULL DEFAULT '#5B8DEF',
          type TEXT DEFAULT 'local',
          sync_url TEXT,
          sync_interval INTEGER DEFAULT 60,
          enabled INTEGER DEFAULT 1,
          created_at INTEGER DEFAULT (unixepoch())
        );

CREATE TABLE settings (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

CREATE TABLE browser_bookmarks (
          id TEXT PRIMARY KEY,
          url TEXT NOT NULL,
          title TEXT NOT NULL,
          favicon TEXT,
          created_at INTEGER DEFAULT (unixepoch())
        , type TEXT DEFAULT 'url', parent_id TEXT, position INTEGER DEFAULT 0, tags TEXT, notes TEXT, source TEXT DEFAULT 'manual');

CREATE TABLE browser_history (
          id TEXT PRIMARY KEY,
          url TEXT NOT NULL,
          title TEXT NOT NULL,
          visited_at INTEGER DEFAULT (unixepoch())
        , favicon TEXT, visit_count INTEGER DEFAULT 1, last_visit_time INTEGER, transition TEXT DEFAULT 'typed', session_id TEXT, domain TEXT DEFAULT '');

CREATE TABLE browser_downloads (
          id TEXT PRIMARY KEY,
          url TEXT NOT NULL,
          filename TEXT NOT NULL,
          save_path TEXT NOT NULL,
          total_bytes INTEGER DEFAULT 0,
          received_bytes INTEGER DEFAULT 0,
          state TEXT DEFAULT 'progressing',
          created_at INTEGER DEFAULT (unixepoch())
        , mime_type TEXT, error TEXT, end_time INTEGER, can_resume INTEGER DEFAULT 0, updated_at INTEGER DEFAULT (unixepoch()));

CREATE TABLE chat_conversations (
          id TEXT PRIMARY KEY,
          agent TEXT NOT NULL,
          title TEXT DEFAULT '',
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        , source_kind TEXT DEFAULT 'local', source_id TEXT DEFAULT 'app', thread_key TEXT DEFAULT '', meta_json TEXT DEFAULT '{}', user_id TEXT, parent_conversation_id TEXT, lineage_root_id TEXT, resume_title TEXT, active_agent_id TEXT, handoff_generation INTEGER NOT NULL DEFAULT 0, closed_at TEXT, closed_reason TEXT, close_evidence_digest TEXT, message_visibility_epoch INTEGER NOT NULL DEFAULT 0);

CREATE TABLE chat_messages (
          id TEXT PRIMARY KEY,
          conversation_id TEXT NOT NULL REFERENCES chat_conversations(id) ON DELETE CASCADE,
          role TEXT NOT NULL,
          content TEXT NOT NULL,
          timestamp TEXT NOT NULL
        , meta_json TEXT DEFAULT '{}', message_visibility_epoch INTEGER NOT NULL DEFAULT -1);

CREATE TABLE skills_jobs (
          id TEXT PRIMARY KEY,
          skill_id TEXT NOT NULL,
          action TEXT NOT NULL,
          params_json TEXT,
          status TEXT NOT NULL,
          trigger_type TEXT NOT NULL DEFAULT 'manual',
          schedule_id TEXT,
          created_at TEXT NOT NULL,
          started_at TEXT,
          finished_at TEXT,
          duration_ms INTEGER,
          stdout TEXT,
          stderr TEXT,
          output_dir TEXT,
          error TEXT,
          command_json TEXT
        );

CREATE TABLE skills_schedules (
          id TEXT PRIMARY KEY,
          skill_id TEXT NOT NULL,
          action TEXT NOT NULL,
          params_json TEXT,
          interval_minutes INTEGER NOT NULL,
          next_run_at TEXT NOT NULL,
          last_run_at TEXT,
          enabled INTEGER NOT NULL DEFAULT 1,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

CREATE TABLE agent_channels (
          id TEXT PRIMARY KEY,
          type TEXT NOT NULL,
          name TEXT NOT NULL,
          enabled INTEGER NOT NULL DEFAULT 1,
          config_json TEXT NOT NULL DEFAULT '{}',
          last_error TEXT,
          last_seen_at TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

CREATE TABLE agent_channel_threads (
          channel_id TEXT NOT NULL,
          remote_thread TEXT NOT NULL,
          session_id TEXT NOT NULL,
          updated_at TEXT NOT NULL, conversation_id TEXT,
          PRIMARY KEY (channel_id, remote_thread),
          FOREIGN KEY (channel_id) REFERENCES agent_channels(id) ON DELETE CASCADE
        );

CREATE TABLE agent_channel_events (
          event_id TEXT PRIMARY KEY,
          channel_id TEXT NOT NULL,
          status TEXT NOT NULL,
          error TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (channel_id) REFERENCES agent_channels(id) ON DELETE CASCADE
        );

CREATE TABLE browser_tasks (
          id TEXT PRIMARY KEY,
          kind TEXT NOT NULL,
          status TEXT NOT NULL,
          payload_json TEXT NOT NULL,
          checkpoint_json TEXT,
          result_json TEXT,
          progress_total INTEGER DEFAULT 0,
          progress_completed INTEGER DEFAULT 0,
          progress_failed INTEGER DEFAULT 0,
          current_label TEXT,
          error TEXT,
          created_at TEXT NOT NULL,
          started_at TEXT,
          updated_at TEXT NOT NULL,
          finished_at TEXT
        , revision INTEGER NOT NULL DEFAULT 0, created_by_run_id TEXT, active_execution_binding_json TEXT, parent_task_id TEXT, projection_revision INTEGER NOT NULL DEFAULT 0, projection_sync_json TEXT);

CREATE VIRTUAL TABLE chat_messages_fts USING fts5(
          message_id UNINDEXED,
          conversation_id UNINDEXED,
          content
        );

CREATE TABLE session_recall_metadata (
          conversation_id TEXT PRIMARY KEY,
          lineage_root_id TEXT NOT NULL,
          resume_title TEXT NOT NULL,
          title TEXT NOT NULL,
          source_kind TEXT NOT NULL,
          source_id TEXT NOT NULL,
          thread_key TEXT NOT NULL,
          user_id TEXT,
          channel_key TEXT NOT NULL,
          preview_text TEXT,
          latest_task_title TEXT,
          latest_task_summary TEXT,
          attachment_names_json TEXT NOT NULL DEFAULT '[]',
          updated_at TEXT NOT NULL
        , agent TEXT);

CREATE TABLE session_recall_attachment_index (
          attachment_key TEXT PRIMARY KEY,
          conversation_id TEXT NOT NULL,
          attachment_id TEXT NOT NULL,
          source_message_id TEXT NOT NULL,
          name TEXT NOT NULL,
          type TEXT,
          ext TEXT,
          path TEXT,
          created_at TEXT NOT NULL
        );

CREATE TABLE session_recall_vectors (
          conversation_id TEXT PRIMARY KEY,
          content_hash TEXT NOT NULL,
          vector_version TEXT NOT NULL,
          vector_json TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

CREATE TABLE task_projections (
          task_id TEXT PRIMARY KEY,
          scope_id TEXT NOT NULL,
          run_id TEXT NOT NULL,
          parent_task_id TEXT,
          parent_step_id TEXT,
          task_type TEXT NOT NULL,
          module TEXT NOT NULL,
          task_title TEXT,
          task_summary TEXT,
          status TEXT NOT NULL,
          interaction_state TEXT NOT NULL,
          waiting_for TEXT,
          steps_json TEXT NOT NULL,
          current_step_id TEXT,
          budget_json TEXT,
          budget_usage_percent INTEGER,
          recovery_history_json TEXT,
          blocked_reason TEXT,
          resumable_actions_json TEXT,
          continuation_ref_json TEXT,
          progress_json TEXT,
          recent_artifacts_json TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        , budget_warning_level TEXT, degradation_reason TEXT, criteria_json TEXT, checkins_json TEXT, proof_refs_json TEXT, learning_refs_json TEXT, owner_agent_id TEXT, packet_role TEXT, context_refs_json TEXT, model_criteria_json TEXT, expected_outputs_json TEXT, task_origin TEXT, execution_binding_json TEXT, delivery_state_json TEXT, revision INTEGER NOT NULL DEFAULT 0, dependency_generation INTEGER NOT NULL DEFAULT 0, request_anchor_json TEXT, goal_mutations_json TEXT, steering_receipts_json TEXT, human_takeover_ref_json TEXT, checkpoint_refs_json TEXT NOT NULL DEFAULT '{"cleanBaseCheckpointId":null,"suspensionCheckpointId":null}', message_visibility_epoch INTEGER NOT NULL DEFAULT 0
        CHECK (message_visibility_epoch >= 0));

CREATE TABLE workspaces (
          id INTEGER PRIMARY KEY,
          root TEXT NOT NULL UNIQUE,
          last_indexed_at INTEGER
        );

CREATE TABLE documents (
          id INTEGER PRIMARY KEY,
          workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
          path TEXT NOT NULL,
          name TEXT NOT NULL,
          ext TEXT,
          size INTEGER,
          mtime INTEGER,
          content_hash TEXT,
          frontmatter_json TEXT,
          indexed_at INTEGER, source_type TEXT NOT NULL DEFAULT 'document', source_meta_json TEXT, source_id TEXT,
          UNIQUE(workspace_id, path)
        );

CREATE VIRTUAL TABLE documents_fts USING fts5(
            name, body,
            tokenize="unicode61 remove_diacritics 2 tokenchars '_-'"
          );

CREATE TABLE tags (
          doc_id INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
          tag TEXT NOT NULL COLLATE NOCASE,
          PRIMARY KEY(doc_id, tag)
        );

CREATE TABLE doc_links (
          src_doc_id INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
          kind TEXT NOT NULL CHECK(kind IN ('wikilink','mdlink')),
          target_text TEXT NOT NULL,
          target_doc_id INTEGER REFERENCES documents(id) ON DELETE SET NULL,
          resolved INTEGER NOT NULL DEFAULT 0,
          PRIMARY KEY(src_doc_id, kind, target_text)
        );

CREATE TABLE doc_attachments (
          doc_id INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
          kind TEXT NOT NULL,
          ref TEXT NOT NULL,
          PRIMARY KEY(doc_id, kind, ref)
        );

CREATE TABLE "skill_task_runs" (
          id TEXT PRIMARY KEY,
          scope_id TEXT,
          session_id TEXT,
          agent TEXT,
          run_id TEXT,
          skill_id TEXT NOT NULL,
          skill_name TEXT,
          action TEXT NOT NULL,
          tool_name TEXT,
          run_kind TEXT NOT NULL,
          status TEXT NOT NULL,
          interaction_state TEXT NOT NULL,
          goal_text TEXT,
          resource_refs_json TEXT,
          params_json TEXT,
          steps_json TEXT NOT NULL DEFAULT '[]',
          current_step_id TEXT,
          artifacts_json TEXT NOT NULL DEFAULT '[]',
          output_dir TEXT,
          run_state_path TEXT,
          scene_scores_path TEXT,
          delivery_report_path TEXT,
          failure_kind TEXT,
          failure_detail TEXT,
          job_id TEXT,
          detached_task_id TEXT,
          resume_payload_json TEXT,
          created_at TEXT NOT NULL,
          started_at TEXT,
          updated_at TEXT NOT NULL,
          finished_at TEXT, message_visibility_epoch INTEGER NOT NULL DEFAULT -1
        CHECK (message_visibility_epoch >= -1),
          CHECK (NOT (run_kind = 'primitive' AND tool_name = 'skill_lifecycle'))
        );

CREATE TABLE run_meta (
          run_id TEXT PRIMARY KEY,
          task_id TEXT,
          scope_id TEXT,
          agent_id TEXT,
          status TEXT NOT NULL,
          input_tokens INTEGER DEFAULT 0,
          output_tokens INTEGER DEFAULT 0,
          total_tokens INTEGER DEFAULT 0,
          first_message_text TEXT,
          last_message_text TEXT,
          follow_up_text TEXT,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        , task_type TEXT, terminal_reason TEXT, provider_protocol TEXT, wire_api TEXT, context_window INTEGER, provider_diagnostics_json TEXT, budget_json TEXT, continuation_ref_json TEXT, recovery_history_json TEXT, initiator TEXT, duration_ms INTEGER, execution_binding_json TEXT, message_visibility_epoch INTEGER NOT NULL DEFAULT -1
        CHECK (message_visibility_epoch >= -1));

CREATE TABLE thread_meta (
          thread_id TEXT PRIMARY KEY,
          scope_id TEXT NOT NULL,
          owner_kind TEXT NOT NULL CHECK (owner_kind IN ('user','agent','system')),
          owner_id TEXT NOT NULL,
          display_title TEXT,
          pinned INTEGER DEFAULT 0,
          archived INTEGER DEFAULT 0,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE run_feedback (
          feedback_id TEXT PRIMARY KEY,
          run_id TEXT NOT NULL,
          task_id TEXT,
          rating INTEGER CHECK (rating BETWEEN 1 AND 5),
          signal TEXT,
          comment TEXT,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          FOREIGN KEY (run_id) REFERENCES run_meta(run_id)
        );

CREATE TABLE "calendar_events" (
          id TEXT PRIMARY KEY,
          calendar_id TEXT NOT NULL,
          title TEXT NOT NULL,
          description TEXT,
          location TEXT,
          start_time INTEGER NOT NULL,
          end_time INTEGER NOT NULL,
          all_day INTEGER DEFAULT 0,
          recurrence_rule TEXT,
          reminders TEXT,
          created_at INTEGER DEFAULT (unixepoch()),
          updated_at INTEGER DEFAULT (unixepoch()), start_tz TEXT, end_tz TEXT, ics_uid TEXT, source_id TEXT,
          FOREIGN KEY (calendar_id) REFERENCES calendar_sources(id) ON DELETE CASCADE
        );

CREATE TABLE calendar_event_overrides (
          id TEXT PRIMARY KEY,
          parent_event_id TEXT NOT NULL,
          occurrence_start INTEGER NOT NULL,
          kind TEXT NOT NULL CHECK (kind IN ('single', 'cancelled')),
          patch_json TEXT,
          created_at INTEGER DEFAULT (unixepoch()),
          updated_at INTEGER DEFAULT (unixepoch()),
          UNIQUE (parent_event_id, occurrence_start),
          FOREIGN KEY (parent_event_id) REFERENCES calendar_events(id) ON DELETE CASCADE
        );

CREATE TABLE "rss_analysis_jobs" (
          id TEXT PRIMARY KEY,
          item_id TEXT NOT NULL,
          action TEXT NOT NULL,
          source_url TEXT NOT NULL,
          title TEXT NOT NULL,
          target_dir TEXT NOT NULL,
          output_dir TEXT NOT NULL,
          report_path TEXT,
          status TEXT NOT NULL,
          progress INTEGER NOT NULL DEFAULT 0,
          message TEXT,
          error TEXT,
          meta_json TEXT,
          created_at TEXT NOT NULL,
          started_at TEXT,
          updated_at TEXT NOT NULL,
          finished_at TEXT
        );

CREATE TABLE document_marks (
          id TEXT PRIMARY KEY,
          kind TEXT NOT NULL CHECK (kind IN ('bookmark', 'note')),
          document_path TEXT NOT NULL,
          title TEXT NOT NULL DEFAULT '',
          group_name TEXT NOT NULL DEFAULT '默认',
          note_text TEXT,
          excerpt TEXT,
          line_start INTEGER,
          line_end INTEGER,
          anchor_title TEXT,
          anchor_ordinal INTEGER,
          anchor_progress REAL,
          anchor_status TEXT NOT NULL DEFAULT 'linked',
          sort_order INTEGER NOT NULL DEFAULT 0,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

CREATE TABLE file_activity_events (
          id TEXT PRIMARY KEY,
          path TEXT NOT NULL,
          workspace_root TEXT,
          event_type TEXT NOT NULL,
          source TEXT NOT NULL,
          weight REAL NOT NULL DEFAULT 1,
          meta_json TEXT,
          created_at INTEGER NOT NULL
        );

CREATE TABLE document_reading_sessions (
          id TEXT PRIMARY KEY,
          path TEXT NOT NULL,
          workspace_root TEXT,
          source TEXT NOT NULL,
          started_at INTEGER NOT NULL,
          ended_at INTEGER NOT NULL,
          active_ms INTEGER NOT NULL,
          progress_start REAL,
          progress_end REAL,
          progress_kind TEXT,
          meta_json TEXT
        );

CREATE TABLE browser_site_experience (
          id TEXT PRIMARY KEY,
          domain TEXT NOT NULL,
          path_pattern TEXT,
          applies_to_task_kinds_json TEXT NOT NULL,
          aliases_json TEXT NOT NULL,
          reliable_entry_patterns_json TEXT NOT NULL,
          generated_link_patterns_json TEXT NOT NULL,
          known_traps_json TEXT NOT NULL,
          selectors_or_target_hints_json TEXT NOT NULL,
          frame_hints_json TEXT NOT NULL,
          risk_level TEXT NOT NULL CHECK (risk_level IN ('low','medium','high')),
          confidence REAL NOT NULL,
          source TEXT NOT NULL CHECK (source IN ('manual','successful-task','test-fixture')),
          last_verified_at TEXT NOT NULL,
          expires_at TEXT,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE pending_task_events (
          id INTEGER PRIMARY KEY,
          event_payload TEXT NOT NULL,
          task_run_id TEXT,
          created_at INTEGER NOT NULL,
          consumed INTEGER NOT NULL DEFAULT 0
        , scope_id TEXT, message_visibility_epoch INTEGER NOT NULL DEFAULT -1
        CHECK (message_visibility_epoch >= -1));

CREATE TABLE pending_confirmations (
          id TEXT PRIMARY KEY,
          run_id TEXT,
          task_id TEXT,
          scope_id TEXT,
          tool_name TEXT NOT NULL,
          params_json TEXT NOT NULL,
          created_at TEXT NOT NULL,
          expires_at TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'pending',
          released_at TEXT
        );

CREATE TABLE agents (
          id TEXT PRIMARY KEY,
          name TEXT NOT NULL,
          charter TEXT,
          persona_ref TEXT,
          status TEXT NOT NULL DEFAULT 'active',
          created_at TEXT NOT NULL
        , parent_agent_id TEXT, derivation_reason TEXT, merged_into_agent_id TEXT);

CREATE TABLE specialist_blueprints (
          blueprint_id TEXT PRIMARY KEY,
          status TEXT NOT NULL,
          specialist_id TEXT,
          source TEXT,
          content_json TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

CREATE TABLE specialist_blueprint_confirmations (
          token_id TEXT PRIMARY KEY,
          blueprint_id TEXT NOT NULL,
          session_id TEXT NOT NULL,
          run_id TEXT,
          blueprint_hash TEXT NOT NULL,
          created_at TEXT NOT NULL,
          used_at TEXT
        );

CREATE TABLE pending_projection_syncs (
          id TEXT PRIMARY KEY,
          status TEXT NOT NULL CHECK(status IN ('pending', 'exhausted')),
          attempts INTEGER NOT NULL DEFAULT 0,
          next_attempt_at TEXT,
          last_error TEXT,
          payload_json TEXT NOT NULL,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

CREATE TABLE specialist_content_edit_proposals (
          proposal_id TEXT PRIMARY KEY,
          agent_id TEXT NOT NULL,
          target_kind TEXT NOT NULL,
          target_rel_path TEXT NOT NULL,
          base_hash TEXT NOT NULL,
          base_content TEXT NOT NULL,
          proposed_content TEXT NOT NULL,
          status TEXT NOT NULL CHECK(status IN ('staged', 'applied', 'rejected', 'conflict')),
          provenance_json TEXT NOT NULL,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          applied_at TEXT
        );

CREATE TABLE agent_identity_migration (
          id TEXT PRIMARY KEY,
          kind TEXT NOT NULL,
          old_agent_id TEXT,
          new_agent_id TEXT,
          details_json TEXT NOT NULL,
          asset_reconciled_at TEXT,
          created_at TEXT NOT NULL
        );

CREATE TABLE file_identities (
          file_key TEXT PRIMARY KEY,
          workspace_root TEXT NOT NULL,
          current_path TEXT NOT NULL,
          status TEXT NOT NULL CHECK(status IN ('present', 'missing', 'deleted')),
          content_hash TEXT,
          observed_since INTEGER NOT NULL,
          last_verified_at INTEGER NOT NULL,
          UNIQUE(workspace_root, current_path)
        );

CREATE TABLE file_move_receipts (
          receipt_id TEXT PRIMARY KEY,
          file_key TEXT NOT NULL REFERENCES file_identities(file_key) ON DELETE CASCADE,
          workspace_root TEXT NOT NULL,
          old_path TEXT NOT NULL,
          new_path TEXT NOT NULL,
          move_kind TEXT NOT NULL CHECK(move_kind IN ('file', 'directory')),
          moved_at INTEGER NOT NULL,
          UNIQUE(file_key, old_path, new_path)
        );

CREATE TABLE project_identities (
          project_key TEXT PRIMARY KEY,
          workspace_root TEXT NOT NULL,
          display_name TEXT NOT NULL,
          source TEXT NOT NULL,
          confidence REAL NOT NULL,
          status TEXT NOT NULL CHECK(status IN ('active', 'snoozed', 'hidden', 'merged')),
          anchor_path TEXT,
          aliases_json TEXT NOT NULL DEFAULT '[]',
          evidence_json TEXT NOT NULL DEFAULT '[]',
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE project_identity_members (
          project_key TEXT NOT NULL REFERENCES project_identities(project_key) ON DELETE CASCADE,
          file_key TEXT NOT NULL REFERENCES file_identities(file_key) ON DELETE CASCADE,
          source TEXT NOT NULL,
          confidence REAL NOT NULL,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          PRIMARY KEY(project_key, file_key)
        );

CREATE TABLE file_attention_rollups (
          file_key TEXT PRIMARY KEY REFERENCES file_identities(file_key) ON DELETE CASCADE,
          observed_since INTEGER NOT NULL,
          history_coverage_start INTEGER NOT NULL,
          history_coverage_end INTEGER NOT NULL,
          first_open_at INTEGER, last_open_at INTEGER,
          first_save_at INTEGER, last_save_at INTEGER,
          first_read_at INTEGER, last_read_at INTEGER,
          open_count INTEGER NOT NULL DEFAULT 0,
          save_count INTEGER NOT NULL DEFAULT 0,
          active_days_json TEXT NOT NULL DEFAULT '[]',
          reading_ms INTEGER NOT NULL DEFAULT 0,
          latest_progress REAL, max_progress REAL, progress_kind TEXT,
          mark_count INTEGER NOT NULL DEFAULT 0,
          link_in_count INTEGER NOT NULL DEFAULT 0,
          link_out_count INTEGER NOT NULL DEFAULT 0,
          last_task_at INTEGER, last_artifact_at INTEGER, last_calendar_at INTEGER, last_attachment_at INTEGER,
          last_surfaced_at INTEGER, last_clicked_at INTEGER, snoozed_until INTEGER, hidden_at INTEGER,
          exists_state TEXT NOT NULL DEFAULT 'present' CHECK(exists_state IN ('present','missing','archived')),
          backfilled_at INTEGER, updated_at INTEGER NOT NULL
        );

CREATE TABLE project_intent_facts (
          intent_id TEXT PRIMARY KEY,
          project_key TEXT NOT NULL REFERENCES project_identities(project_key) ON DELETE CASCADE,
          file_keys_json TEXT NOT NULL DEFAULT '[]',
          kind TEXT NOT NULL CHECK(kind IN ('continue','prepare','deliver','read')),
          source TEXT NOT NULL CHECK(source IN ('calendar','task','user_confirmed')),
          not_before INTEGER, due_at INTEGER, expires_at INTEGER NOT NULL,
          status TEXT NOT NULL CHECK(status IN ('active','completed','cancelled','expired')),
          evidence_code TEXT NOT NULL,
          evidence_ref TEXT,
          created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
        );

CREATE TABLE file_emergence_prediction_snapshots (
          snapshot_id TEXT NOT NULL,
          project_key TEXT NOT NULL,
          bucket TEXT NOT NULL CHECK(bucket IN ('future','today','past','distant')),
          reason_codes_json TEXT NOT NULL,
          generated_at INTEGER NOT NULL, rank INTEGER, score REAL, machine_name INTEGER NOT NULL DEFAULT 0, file_keys_json TEXT NOT NULL DEFAULT '[]',
          PRIMARY KEY(snapshot_id, project_key)
        );

CREATE TABLE tag_lexicon_overlays (
          tag_id TEXT PRIMARY KEY,
          facet TEXT NOT NULL CHECK(facet IN ('form','domain','entity','use','state')),
          label TEXT NOT NULL,
          aliases_json TEXT NOT NULL DEFAULT '[]',
          definition TEXT NOT NULL DEFAULT '',
          status TEXT NOT NULL CHECK(status IN ('active','deprecated')),
          created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
        );

CREATE TABLE file_tag_assignments (
          file_key TEXT NOT NULL REFERENCES file_identities(file_key) ON DELETE CASCADE,
          tag_id TEXT NOT NULL,
          facet TEXT NOT NULL CHECK(facet IN ('form','domain','entity','use','state')),
          label TEXT NOT NULL,
          source TEXT NOT NULL CHECK(source IN ('user','tag_forge_auto','tag_forge_explicit','import')),
          ownership TEXT NOT NULL CHECK(ownership IN ('manual','automatic')),
          suppressed INTEGER NOT NULL DEFAULT 0,
          lexicon_version TEXT,
          evidence_code TEXT,
          confidence REAL,
          validated_at INTEGER,
          written_at INTEGER,
          readback_at INTEGER,
          updated_at INTEGER NOT NULL,
          PRIMARY KEY(file_key,tag_id)
        );

CREATE TABLE artifact_creation_receipts (
          receipt_id TEXT PRIMARY KEY,
          source_run_id TEXT NOT NULL,
          file_key TEXT NOT NULL REFERENCES file_identities(file_key) ON DELETE CASCADE,
          created_in_this_run INTEGER NOT NULL CHECK(created_in_this_run=1),
          created_at INTEGER NOT NULL,
          final_save_hash TEXT,
          final_saved_at INTEGER,
          enrichment_status TEXT NOT NULL CHECK(enrichment_status IN ('awaiting_final_save','pending','completed','completed_sparse','failed_retryable','failed_terminal')),
          retry_error_code TEXT,
          updated_at INTEGER NOT NULL, validation_json TEXT,
          UNIQUE(source_run_id,file_key)
        );

CREATE TABLE file_emergence_feedback (
          feedback_id TEXT PRIMARY KEY,
          project_key TEXT NOT NULL REFERENCES project_identities(project_key) ON DELETE CASCADE,
          action TEXT NOT NULL CHECK(action IN ('rename','not_related','snooze','hide','restore')),
          evidence_cutoff INTEGER,
          snooze_until INTEGER,
          created_at INTEGER NOT NULL
        );

CREATE TABLE file_emergence_snapshot_generations (
          snapshot_id TEXT PRIMARY KEY,
          root_scope_hash TEXT NOT NULL,
          generated_at INTEGER NOT NULL,
          visible_count INTEGER NOT NULL,
          machine_name_count INTEGER NOT NULL,
          rejection_reasons_json TEXT NOT NULL
        );

CREATE TABLE scheduled_tasks (
          id TEXT PRIMARY KEY,
          name TEXT NOT NULL,
          instruction TEXT NOT NULL,
          schedule_spec_version INTEGER NOT NULL DEFAULT 1 CHECK(schedule_spec_version = 1),
          schedule_spec_json TEXT NOT NULL,
          timezone TEXT NOT NULL,
          scope_id TEXT,
          scope_mode TEXT NOT NULL DEFAULT 'existing' CHECK(scope_mode IN ('dedicated', 'existing')),
          agent_id TEXT NOT NULL,
          workspace_roots_json TEXT NOT NULL DEFAULT '[]',
          enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1)),
          next_run_at TEXT,
          last_occurrence_at TEXT,
          missed_policy TEXT NOT NULL DEFAULT 'coalesce_latest'
            CHECK(missed_policy IN ('coalesce_latest', 'skip')),
          migration_state TEXT CHECK(migration_state IN ('needs_scope', 'needs_schedule_review')),
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          deleted_at TEXT
        );

CREATE TABLE agent_schedule_occurrences (
          id TEXT PRIMARY KEY,
          schedule_id TEXT NOT NULL REFERENCES scheduled_tasks(id) ON DELETE RESTRICT,
          scheduled_for TEXT NOT NULL,
          triggered_at TEXT NOT NULL,
          trigger_source TEXT NOT NULL
            CHECK(trigger_source IN ('timer', 'startup', 'resume', 'manual')),
          trigger_source_key TEXT NOT NULL,
          claim_status TEXT NOT NULL
            CHECK(claim_status IN (
              'queued', 'dispatching', 'dispatched', 'dispatch_failed',
              'skipped_missed', 'skipped_coalesced', 'blocked_target'
            )),
          attempt INTEGER NOT NULL DEFAULT 0 CHECK(attempt >= 0),
          run_id TEXT,
          task_id TEXT,
          delay_ms INTEGER NOT NULL DEFAULT 0 CHECK(delay_ms >= 0),
          started_at TEXT,
          finished_at TEXT,
          error_kind TEXT,
          error_message TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE(schedule_id, scheduled_for, trigger_source_key)
        );

CREATE TABLE tag_pending_proposals (
          proposal_id TEXT PRIMARY KEY,
          facet TEXT NOT NULL CHECK(facet IN ('form','domain','entity','use','state')),
          label TEXT NOT NULL,
          evidence_code TEXT NOT NULL,
          evidence_excerpt TEXT,
          source_run_id TEXT,
          batch_id TEXT NOT NULL,
          item_id TEXT NOT NULL,
          scope_id TEXT,
          status TEXT NOT NULL CHECK(status IN ('pending','approved','merged','rejected','dismissed')),
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          UNIQUE(batch_id,item_id,facet,label,status)
        );

CREATE TABLE browser_power_preflight_audit (
          id TEXT PRIMARY KEY,
          tool_name TEXT NOT NULL,
          grant_id TEXT NOT NULL,
          confirmation_source TEXT NOT NULL,
          scope_id TEXT,
          tab_id TEXT,
          document_key_hash TEXT NOT NULL,
          url TEXT,
          object_ref TEXT,
          effects_json TEXT NOT NULL,
          purpose TEXT,
          input_hash TEXT NOT NULL,
          created_at TEXT NOT NULL
        );

CREATE TABLE agent_session_checkpoints (
          checkpoint_id TEXT PRIMARY KEY,
          role TEXT NOT NULL CHECK (role IN ('clean_base', 'suspension')),
          parent_task_id TEXT NOT NULL,
          browser_task_id TEXT,
          owner_run_id TEXT NOT NULL,
          ancestor_owner_run_id TEXT,
          ancestor_checkpoint_digest TEXT,
          schema_major INTEGER NOT NULL,
          serializer_major INTEGER NOT NULL,
          registry_major INTEGER NOT NULL,
          safety_major INTEGER NOT NULL,
          final_input_json TEXT NOT NULL,
          final_input_digest TEXT NOT NULL,
          sdk_source_item_count INTEGER NOT NULL,
          sdk_source_prefix_digest TEXT NOT NULL,
          last_effective_browser_action_seq INTEGER NOT NULL DEFAULT 0,
          steering_receipt_ids_json TEXT NOT NULL,
          steering_receipt_digests_json TEXT NOT NULL,
          required_operation_ids_json TEXT NOT NULL,
          resource_refs_json TEXT NOT NULL,
          prepared_skill_json TEXT NOT NULL,
          activated_capability_groups_json TEXT NOT NULL,
          created_at TEXT NOT NULL
        );

CREATE TABLE agent_checkpoint_wake_receipts (
          wake_id TEXT PRIMARY KEY,
          parent_task_id TEXT NOT NULL,
          checkpoint_id TEXT NOT NULL,
          basis_revision INTEGER NOT NULL,
          kind TEXT NOT NULL CHECK (kind IN ('user_continue', 'browser_power_confirmation', 'browser_permission', 'steering', 'human_takeover', 'provider_transfer', 'background_ready', 'foreground_resume', 'capability_revision', 'config_revision', 'owner_crash')),
          source_id TEXT NOT NULL,
          source_digest TEXT NOT NULL,
          issued_at TEXT NOT NULL,
          consumed_by_run_id TEXT,
          consumed_at TEXT
        );

CREATE TABLE agent_steering_message_resources (
          resource_id TEXT PRIMARY KEY,
          message_id TEXT NOT NULL,
          ordinal INTEGER NOT NULL,
          block_type TEXT NOT NULL CHECK (block_type IN ('text', 'image', 'video')),
          media_type TEXT,
          content TEXT NOT NULL,
          content_digest TEXT NOT NULL,
          provenance_digest TEXT NOT NULL,
          created_at TEXT NOT NULL,
          UNIQUE(message_id, ordinal)
        );

CREATE TABLE browser_target_claims (
          partition TEXT NOT NULL,
          tab_id TEXT NOT NULL,
          physical_target_token TEXT,
          boot_incarnation_id TEXT,
          claim_id TEXT NOT NULL UNIQUE,
          generation INTEGER NOT NULL,
          profile_id TEXT,
          surface TEXT NOT NULL,
          parent_task_id TEXT NOT NULL,
          browser_task_id TEXT NOT NULL,
          owner_run_id TEXT NOT NULL,
          scope_id TEXT,
          session_id TEXT,
          message_visibility_epoch INTEGER,
          state TEXT NOT NULL,
          suspension_checkpoint_id TEXT,
          suspension_reason TEXT,
          acquired_at INTEGER NOT NULL,
          heartbeat_at INTEGER NOT NULL,
          expires_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          PRIMARY KEY (partition, tab_id),
          CHECK (generation >= 1),
          CHECK (surface IN ('user-view', 'agent-view')),
          CHECK (state IN ('held', 'user_owned', 'suspended', 'expired', 'released')),
          CHECK ((physical_target_token IS NULL) = (boot_incarnation_id IS NULL)),
          CHECK (state != 'held' OR physical_target_token IS NOT NULL),
          CHECK (
            (state = 'suspended'
              AND suspension_checkpoint_id IS NOT NULL AND suspension_reason IS NOT NULL)
            OR (state = 'user_owned' AND suspension_reason IS NOT NULL)
            OR (state IN ('held', 'expired', 'released')
              AND suspension_checkpoint_id IS NULL AND suspension_reason IS NULL)
          )
        );

CREATE TABLE browser_control_receipts (
          receipt_id TEXT PRIMARY KEY,
          sequence INTEGER NOT NULL,
          parent_task_id TEXT NOT NULL,
          browser_task_id TEXT NOT NULL,
          owner_run_id TEXT NOT NULL,
          partition TEXT,
          tab_id TEXT,
          physical_target_token TEXT,
          boot_incarnation_id TEXT,
          previous_claim_id TEXT,
          previous_generation INTEGER,
          next_claim_id TEXT,
          next_generation INTEGER,
          clean_base_checkpoint_id TEXT,
          suspension_checkpoint_id TEXT,
          wake_id TEXT,
          successor_run_id TEXT,
          continuation_generation INTEGER,
          idempotency_key TEXT NOT NULL UNIQUE,
          kind TEXT NOT NULL,
          error_code TEXT,
          recoverable INTEGER NOT NULL,
          created_at TEXT NOT NULL
        );

CREATE TABLE codex_thread_bindings (
    thread_binding_id TEXT PRIMARY KEY,
    codex_thread_id TEXT UNIQUE,
    codex_session_id TEXT,
    codex_parent_thread_id TEXT,
    codex_forked_from_id TEXT,
    codex_source_json TEXT,
    codex_thread_source_json TEXT,
    thread_start_reservation_set_id TEXT UNIQUE,
    thread_start_reservation_member_id TEXT UNIQUE,
    thread_start_reservation_admitted_at TEXT,
    thread_start_reservation_released_at TEXT,
    thread_start_reservation_release_reason TEXT,
    thread_start_request_id TEXT UNIQUE,
    thread_start_rpc_connection_epoch TEXT,
    thread_start_rpc_id INTEGER,
    thread_start_dispatch_intent_at TEXT,
    thread_start_child_write_confirmed_at TEXT,
    thread_start_child_write_digest TEXT,
    thread_start_response_at TEXT,
    thread_start_reconciled_at TEXT,
    thread_start_reconciliation_evidence_digest TEXT,
    thread_start_late_response_guard_closed_at TEXT,
    thread_start_late_response_guard_close_reason TEXT,
    isolated_thread_cwd TEXT UNIQUE,
    ready_conversation_alias TEXT NOT NULL,
    alias_generation INTEGER NOT NULL,
    ready_scope_id TEXT NOT NULL,
    runtime_manifest_digest TEXT NOT NULL,
    protocol_schema_digest TEXT NOT NULL,
    tool_surface_digest TEXT,
    tool_surface_snapshot_digest TEXT,
    tool_surface_json TEXT,
    instruction_contract_digest TEXT,
    codex_model_provider_id TEXT CHECK (codex_model_provider_id = 'ready_gateway'),
    codex_model TEXT,
    upstream_profile_snapshot_ref TEXT,
    upstream_profile_snapshot_digest TEXT,
    thread_started_at TEXT,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    retired_at TEXT,
    retired_reason TEXT CHECK (retired_reason IN (
      'user_reset', 'closed', 'publication_diverged', 'manual_compaction_quarantine', 'cleanup'
    )),
    retirement_evidence_digest TEXT,
    continuation_blocked_at TEXT,
    continuation_blocked_reason TEXT CHECK (continuation_blocked_reason IN (
      'start_delivery_absent', 'publication_diverged'
    )),
    continuation_blocked_evidence_digest TEXT,
    CHECK (alias_generation >= 1),
    CHECK (
      (thread_start_reservation_set_id IS NULL
        AND thread_start_reservation_member_id IS NULL
        AND thread_start_reservation_admitted_at IS NULL
        AND thread_start_request_id IS NULL
        AND isolated_thread_cwd IS NULL
        AND tool_surface_digest IS NULL
        AND tool_surface_snapshot_digest IS NULL
        AND tool_surface_json IS NULL
        AND instruction_contract_digest IS NULL
        AND codex_model_provider_id IS NULL
        AND codex_model IS NULL
        AND upstream_profile_snapshot_ref IS NULL
        AND upstream_profile_snapshot_digest IS NULL)
      OR
      (thread_start_reservation_set_id IS NOT NULL
        AND thread_start_reservation_member_id IS NOT NULL
        AND thread_start_reservation_admitted_at IS NOT NULL
        AND thread_start_request_id IS NOT NULL
        AND isolated_thread_cwd IS NOT NULL
        AND tool_surface_digest IS NOT NULL
        AND tool_surface_snapshot_digest IS NOT NULL
        AND tool_surface_json IS NOT NULL
        AND instruction_contract_digest IS NOT NULL
        AND codex_model_provider_id = 'ready_gateway'
        AND codex_model IS NOT NULL
        AND upstream_profile_snapshot_ref IS NOT NULL
        AND upstream_profile_snapshot_digest IS NOT NULL)
    ),
    CHECK ((thread_start_reservation_released_at IS NULL) = (thread_start_reservation_release_reason IS NULL)),
    CHECK (
      (thread_start_dispatch_intent_at IS NULL
        AND thread_start_rpc_connection_epoch IS NULL AND thread_start_rpc_id IS NULL)
      OR
      (thread_start_dispatch_intent_at IS NOT NULL
        AND thread_start_rpc_connection_epoch IS NOT NULL AND thread_start_rpc_id IS NOT NULL)
    ),
    CHECK ((thread_start_child_write_confirmed_at IS NULL) = (thread_start_child_write_digest IS NULL)),
    CHECK (thread_start_child_write_confirmed_at IS NULL OR thread_start_dispatch_intent_at IS NOT NULL),
    CHECK (
      (thread_start_reconciled_at IS NULL
        AND thread_start_reconciliation_evidence_digest IS NULL AND codex_thread_id IS NULL
        AND codex_session_id IS NULL AND thread_started_at IS NULL)
      OR
      (thread_start_reconciled_at IS NOT NULL
        AND thread_start_reconciliation_evidence_digest IS NOT NULL AND codex_thread_id IS NOT NULL
        AND codex_session_id IS NOT NULL AND thread_started_at IS NOT NULL)
    ),
    CHECK (thread_start_response_at IS NULL OR thread_start_dispatch_intent_at IS NOT NULL),
    CHECK (
      (thread_start_late_response_guard_closed_at IS NULL)
      = (thread_start_late_response_guard_close_reason IS NULL)
    ),
    CHECK (thread_start_late_response_guard_closed_at IS NULL OR thread_start_reconciled_at IS NOT NULL),
    CHECK ((retired_at IS NULL AND retired_reason IS NULL AND retirement_evidence_digest IS NULL)
      OR (retired_at IS NOT NULL AND retired_reason IS NOT NULL AND retirement_evidence_digest IS NOT NULL)),
    CHECK ((continuation_blocked_at IS NULL AND continuation_blocked_reason IS NULL
      AND continuation_blocked_evidence_digest IS NULL)
      OR (continuation_blocked_at IS NOT NULL AND continuation_blocked_reason IS NOT NULL
      AND continuation_blocked_evidence_digest IS NOT NULL))
  );

CREATE TABLE codex_turn_bindings (
    ready_run_id TEXT PRIMARY KEY,
    ready_task_id TEXT NOT NULL,
    thread_binding_id TEXT NOT NULL,
    codex_thread_id TEXT,
    codex_turn_id TEXT,
    start_reservation_set_id TEXT NOT NULL UNIQUE,
    start_reservation_required_member_count INTEGER NOT NULL CHECK (
      start_reservation_required_member_count IN (1, 2)
    ),
    turn_start_reservation_member_id TEXT NOT NULL UNIQUE,
    turn_start_reservation_admitted_at TEXT NOT NULL,
    turn_start_reservation_released_at TEXT,
    turn_start_reservation_release_reason TEXT,
    turn_request_id TEXT NOT NULL UNIQUE,
    turn_start_rpc_connection_epoch TEXT,
    turn_start_rpc_id INTEGER,
    turn_start_dispatch_intent_at TEXT,
    turn_start_child_write_confirmed_at TEXT,
    turn_start_child_write_digest TEXT,
    turn_start_response_at TEXT,
    turn_start_reconciled_at TEXT,
    turn_start_reconciliation_evidence_digest TEXT,
    turn_start_late_response_guard_closed_at TEXT,
    turn_start_late_response_guard_close_reason TEXT,
    host_failure_kind TEXT CHECK (host_failure_kind IN (
      'sidecar_spawn_failed', 'thread_start_rpc_rejected',
      'thread_start_delivery_proven_absent', 'turn_start_rpc_rejected',
      'turn_start_delivery_proven_absent'
    )),
    host_failure_recorded_at TEXT,
    host_failure_evidence_digest TEXT,
    host_failure_product_terminal_digest TEXT,
    host_failure_closeout_at TEXT,
    recovery_failure_code TEXT,
    recovery_failure_evidence_digest TEXT,
    recovery_failure_recorded_at TEXT,
    product_terminal_digest TEXT,
    product_closeout_at TEXT,
    origin_user_message_id TEXT,
    message_visibility_epoch INTEGER NOT NULL DEFAULT 0 CHECK (message_visibility_epoch >= 0),
    ingress_admitted_revision INTEGER NOT NULL CHECK (ingress_admitted_revision >= 1),
    ingress_admitted_digest TEXT NOT NULL,
    ingress_admitted_at TEXT NOT NULL,
    predecessor_run_id TEXT,
    attempt_kind TEXT NOT NULL CHECK (attempt_kind IN (
      'user_ingress', 'recovery_successor', 'checkpoint_successor', 'explicit_retry'
    )),
    history_parity_evidence_digest TEXT,
    current_thread_read_evidence_digest TEXT,
    continuation_contract_digest TEXT,
    tool_surface_digest TEXT NOT NULL,
    authorization_snapshot_digest TEXT NOT NULL,
    authorization_snapshot_json TEXT NOT NULL,
    product_budget_seed_json TEXT NOT NULL,
    effective_codex_model TEXT NOT NULL,
    effective_upstream_snapshot_ref TEXT NOT NULL,
    effective_upstream_snapshot_digest TEXT NOT NULL,
    additional_context_digest TEXT NOT NULL,
    ready_memory_snapshot_json TEXT CHECK (
      ready_memory_snapshot_json IS NULL OR (
        json_valid(ready_memory_snapshot_json) AND json_type(ready_memory_snapshot_json) = 'object'
      )
    ),
    ready_memory_snapshot_digest TEXT CHECK (
      ready_memory_snapshot_digest IS NULL OR (
        length(ready_memory_snapshot_digest) = 64
        AND ready_memory_snapshot_digest NOT GLOB '*[^0-9a-f]*'
      )
    ),
    ready_memory_state_revision INTEGER CHECK (
      ready_memory_state_revision IS NULL OR ready_memory_state_revision >= 1
    ),
    ready_memory_revocation_revision INTEGER CHECK (
      ready_memory_revocation_revision IS NULL OR ready_memory_revocation_revision >= 0
    ),
    ready_memory_read_receipt_json TEXT CHECK (
      ready_memory_read_receipt_json IS NULL OR (
        json_valid(ready_memory_read_receipt_json)
        AND json_type(ready_memory_read_receipt_json) = 'object'
      )
    ),
    ready_memory_read_receipt_digest TEXT CHECK (
      ready_memory_read_receipt_digest IS NULL OR (
        length(ready_memory_read_receipt_digest) = 64
        AND ready_memory_read_receipt_digest NOT GLOB '*[^0-9a-f]*'
      )
    ),
    turn_contract_digest TEXT NOT NULL,
    ingress_json TEXT NOT NULL,
    interrupt_requested_at TEXT,
    interrupt_ack_at TEXT,
    interrupt_state_unknown_at TEXT,
    lifecycle_action TEXT CHECK (lifecycle_action IN ('stop', 'close', 'reset')),
    lifecycle_action_requested_at TEXT,
    lifecycle_action_evidence_digest TEXT,
    engine_terminal_status TEXT CHECK (engine_terminal_status IN ('completed', 'interrupted', 'failed')),
    engine_terminal_candidate_json TEXT,
    engine_terminal_candidate_digest TEXT,
    engine_terminal_recorded_at TEXT,
    publication_receipt_refs_json TEXT,
    publication_receipt_digest TEXT,
    publication_recorded_at TEXT,
    fence_release_revision INTEGER CHECK (fence_release_revision >= 2),
    revision INTEGER NOT NULL CHECK (revision >= 1),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL, gateway_claimed_codex_turn_id TEXT,
    UNIQUE(codex_thread_id, codex_turn_id),
    CHECK ((turn_start_reservation_released_at IS NULL) = (turn_start_reservation_release_reason IS NULL)),
    CHECK (
      (turn_start_dispatch_intent_at IS NULL
        AND turn_start_rpc_connection_epoch IS NULL AND turn_start_rpc_id IS NULL)
      OR
      (turn_start_dispatch_intent_at IS NOT NULL
        AND turn_start_rpc_connection_epoch IS NOT NULL AND turn_start_rpc_id IS NOT NULL)
    ),
    CHECK (
      (publication_receipt_refs_json IS NULL AND publication_receipt_digest IS NULL
        AND publication_recorded_at IS NULL)
      OR
      (publication_receipt_refs_json IS NOT NULL AND publication_receipt_digest IS NOT NULL
        AND publication_recorded_at IS NOT NULL AND engine_terminal_recorded_at IS NOT NULL)
    ),
    CHECK ((turn_start_child_write_confirmed_at IS NULL) = (turn_start_child_write_digest IS NULL)),
    CHECK (turn_start_child_write_confirmed_at IS NULL OR turn_start_dispatch_intent_at IS NOT NULL),
    CHECK (
      (turn_start_reconciled_at IS NULL
        AND turn_start_reconciliation_evidence_digest IS NULL AND codex_turn_id IS NULL)
      OR
      (turn_start_reconciled_at IS NOT NULL
        AND turn_start_reconciliation_evidence_digest IS NOT NULL AND codex_turn_id IS NOT NULL
        AND codex_thread_id IS NOT NULL)
    ),
    CHECK (turn_start_response_at IS NULL OR turn_start_dispatch_intent_at IS NOT NULL),
    CHECK (
      (turn_start_late_response_guard_closed_at IS NULL)
      = (turn_start_late_response_guard_close_reason IS NULL)
    ),
    CHECK (turn_start_late_response_guard_closed_at IS NULL OR turn_start_reconciled_at IS NOT NULL),
    CHECK (
      (host_failure_kind IS NULL AND host_failure_recorded_at IS NULL
        AND host_failure_evidence_digest IS NULL AND host_failure_product_terminal_digest IS NULL)
      OR
      (host_failure_kind IS NOT NULL AND host_failure_recorded_at IS NOT NULL
        AND host_failure_evidence_digest IS NOT NULL)
    ),
    CHECK (
      (host_failure_product_terminal_digest IS NULL) = (host_failure_closeout_at IS NULL)
    ),
    CHECK (
      (recovery_failure_code IS NULL
        AND recovery_failure_evidence_digest IS NULL
        AND recovery_failure_recorded_at IS NULL)
      OR
      (recovery_failure_code IS NOT NULL
        AND recovery_failure_evidence_digest IS NOT NULL
        AND recovery_failure_recorded_at IS NOT NULL)
    ),
    CHECK (recovery_failure_code IS NULL OR host_failure_kind IS NULL),
    CHECK ((product_terminal_digest IS NULL) = (product_closeout_at IS NULL)),
    CHECK (
      (lifecycle_action IS NULL AND lifecycle_action_requested_at IS NULL
        AND lifecycle_action_evidence_digest IS NULL)
      OR
      (lifecycle_action IS NOT NULL AND lifecycle_action_requested_at IS NOT NULL
        AND lifecycle_action_evidence_digest IS NOT NULL
        AND length(lifecycle_action_evidence_digest) = 64
        AND lifecycle_action_evidence_digest NOT GLOB '*[^0-9a-f]*')
    ),
    CHECK (
      (engine_terminal_status IS NULL AND engine_terminal_candidate_json IS NULL
        AND engine_terminal_candidate_digest IS NULL AND engine_terminal_recorded_at IS NULL)
      OR
      (engine_terminal_status IS NOT NULL AND engine_terminal_candidate_json IS NOT NULL
        AND engine_terminal_candidate_digest IS NOT NULL AND engine_terminal_recorded_at IS NOT NULL)
    ),
    CHECK (fence_release_revision IS NULL
      OR product_terminal_digest IS NOT NULL
      OR host_failure_product_terminal_digest IS NOT NULL),
    CHECK (
      (attempt_kind = 'user_ingress' AND origin_user_message_id IS NOT NULL
        AND predecessor_run_id IS NULL AND history_parity_evidence_digest IS NULL
        AND current_thread_read_evidence_digest IS NULL AND continuation_contract_digest IS NULL)
      OR
      (attempt_kind IN ('recovery_successor', 'checkpoint_successor', 'explicit_retry')
        AND predecessor_run_id IS NOT NULL AND history_parity_evidence_digest IS NOT NULL
        AND current_thread_read_evidence_digest IS NOT NULL AND continuation_contract_digest IS NOT NULL)
    )
  );

CREATE TABLE codex_tool_call_bindings (
    codex_thread_id TEXT NOT NULL,
    codex_turn_id TEXT NOT NULL,
    codex_call_id TEXT NOT NULL,
    ready_run_id TEXT NOT NULL,
    ready_action_id TEXT NOT NULL UNIQUE,
    tool_name TEXT NOT NULL,
    args_digest TEXT NOT NULL,
    turn_contract_digest TEXT NOT NULL,
    ready_alias_id TEXT NOT NULL,
    codex_session_id TEXT NOT NULL,
    ready_task_id TEXT NOT NULL,
    surface_snapshot_digest TEXT NOT NULL,
    tool_surface_digest TEXT NOT NULL,
    authorization_snapshot_digest TEXT NOT NULL,
    tool_schema_digest TEXT NOT NULL,
    request_connection_epoch TEXT NOT NULL,
    request_rpc_id TEXT NOT NULL,
    receipt_id TEXT UNIQUE,
    result_digest TEXT,
    delivered_connection_epoch TEXT,
    delivered_rpc_id TEXT,
    tool_response_digest TEXT,
    legacy_delivery_evidence_unverifiable INTEGER NOT NULL DEFAULT 0
      CHECK (legacy_delivery_evidence_unverifiable IN (0, 1)),
    delivery_intent_at TEXT,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (codex_thread_id, codex_turn_id, codex_call_id),
    CHECK ((receipt_id IS NULL) = (result_digest IS NULL)),
    CHECK ((delivered_connection_epoch IS NULL) = (delivered_rpc_id IS NULL)),
    CHECK ((delivered_connection_epoch IS NULL) = (delivery_intent_at IS NULL)),
    CHECK (tool_response_digest IS NULL OR (
      length(tool_response_digest) = 64
      AND tool_response_digest NOT GLOB '*[^0-9a-f]*'
    ))
  );

CREATE TABLE ready_tool_action_receipts (
    ready_action_id TEXT PRIMARY KEY,
    action_identity_digest TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('pending', 'confirmed', 'proven_absent', 'indeterminate')),
    receipt_id TEXT UNIQUE,
    result_digest TEXT,
    result_json TEXT,
    resolution_reason TEXT,
    resolution_evidence_digest TEXT,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CHECK (
      (state = 'pending' AND receipt_id IS NULL AND result_digest IS NULL AND result_json IS NULL
        AND resolution_reason IS NULL AND resolution_evidence_digest IS NULL)
      OR (state = 'confirmed' AND receipt_id IS NOT NULL AND result_digest IS NOT NULL
        AND result_json IS NOT NULL AND resolution_reason IS NULL AND resolution_evidence_digest IS NULL)
      OR (state IN ('proven_absent', 'indeterminate') AND receipt_id IS NULL
        AND result_digest IS NULL AND result_json IS NULL
        AND resolution_reason IS NOT NULL AND resolution_evidence_digest IS NOT NULL)
    )
  );

CREATE TABLE codex_tool_response_delivery_attempts (
    attempt_id TEXT PRIMARY KEY,
    codex_thread_id TEXT NOT NULL,
    codex_turn_id TEXT NOT NULL,
    codex_call_id TEXT NOT NULL,
    ready_action_id TEXT NOT NULL,
    connection_epoch TEXT NOT NULL,
    request_rpc_id TEXT NOT NULL,
    tool_response_json TEXT NOT NULL,
    tool_response_digest TEXT NOT NULL CHECK (
      length(tool_response_digest) = 64
      AND tool_response_digest NOT GLOB '*[^0-9a-f]*'
    ),
    transport_write_confirmed_at TEXT,
    created_at TEXT NOT NULL,
    UNIQUE (connection_epoch, request_rpc_id),
    UNIQUE (
      codex_thread_id, codex_turn_id, codex_call_id,
      connection_epoch, request_rpc_id
    ),
    FOREIGN KEY (codex_thread_id, codex_turn_id, codex_call_id)
      REFERENCES codex_tool_call_bindings(codex_thread_id, codex_turn_id, codex_call_id)
  );

CREATE TABLE codex_tool_request_rpc_bindings (
    connection_epoch TEXT NOT NULL,
    request_rpc_id TEXT NOT NULL,
    codex_thread_id TEXT NOT NULL,
    codex_turn_id TEXT NOT NULL,
    codex_call_id TEXT NOT NULL,
    ready_action_id TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY (connection_epoch, request_rpc_id),
    FOREIGN KEY (codex_thread_id, codex_turn_id, codex_call_id)
      REFERENCES codex_tool_call_bindings(codex_thread_id, codex_turn_id, codex_call_id)
  );

CREATE TABLE codex_manual_compaction_bindings (
    manual_compaction_id TEXT PRIMARY KEY,
    thread_binding_id TEXT NOT NULL,
    codex_thread_id TEXT NOT NULL,
    codex_compaction_turn_id TEXT,
    codex_model_provider_id TEXT NOT NULL CHECK (codex_model_provider_id = 'ready_gateway'),
    codex_model TEXT NOT NULL,
    upstream_profile_snapshot_ref TEXT NOT NULL,
    upstream_profile_snapshot_digest TEXT NOT NULL,
    provider_snapshot_json TEXT NOT NULL,
    credential_reference_id TEXT NOT NULL,
    expected_tools_digest TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    consumed_at TEXT,
    consume_evidence_digest TEXT,
    abandoned_at TEXT,
    abandoned_reason TEXT,
    abandoned_reconciled_at TEXT,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL, pre_dispatch_thread_read_digest TEXT, pre_dispatch_turn_ids_json TEXT, pre_dispatch_turn_ids_digest TEXT, unknown_at TEXT, unknown_reason TEXT, unknown_evidence_digest TEXT, context_compaction_item_id TEXT, terminal_status TEXT, terminal_evidence_digest TEXT, thread_read_digest TEXT, gateway_request_receipt_id TEXT, gateway_request_evidence_digest TEXT, gateway_response_evidence_digest TEXT, notification_context_compaction_item_id TEXT,
    CHECK ((consumed_at IS NULL) = (consume_evidence_digest IS NULL)),
    CHECK (NOT (consumed_at IS NOT NULL AND abandoned_at IS NOT NULL)),
    CHECK ((abandoned_at IS NULL AND abandoned_reason IS NULL AND abandoned_reconciled_at IS NULL)
      OR (abandoned_at IS NOT NULL AND abandoned_reason IS NOT NULL))
  );

CREATE TABLE codex_thread_dispatch_fences (
    thread_binding_id TEXT PRIMARY KEY,
    owner_main_boot_id TEXT NOT NULL,
    operation_kind TEXT NOT NULL CHECK (operation_kind IN ('product_turn', 'manual_compaction')),
    owner_ready_run_id TEXT,
    owner_manual_compaction_id TEXT,
    acquired_at TEXT NOT NULL,
    expires_at TEXT,
    quarantined_at TEXT,
    quarantine_reason TEXT,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    CHECK ((owner_ready_run_id IS NULL) != (owner_manual_compaction_id IS NULL)),
    CHECK (
      (operation_kind = 'product_turn' AND owner_ready_run_id IS NOT NULL
        AND owner_manual_compaction_id IS NULL)
      OR
      (operation_kind = 'manual_compaction' AND owner_manual_compaction_id IS NOT NULL
        AND owner_ready_run_id IS NULL)
    ),
    CHECK ((quarantined_at IS NULL) = (quarantine_reason IS NULL))
  );

CREATE TABLE codex_fence_owner_transfers (
    transfer_id TEXT PRIMARY KEY,
    thread_binding_id TEXT NOT NULL,
    operation_kind TEXT NOT NULL CHECK (operation_kind IN ('product_turn', 'manual_compaction')),
    owner_ready_run_id TEXT,
    owner_manual_compaction_id TEXT,
    previous_owner_main_boot_id TEXT NOT NULL,
    new_owner_main_boot_id TEXT NOT NULL,
    previous_fence_revision INTEGER NOT NULL,
    new_fence_revision INTEGER NOT NULL,
    process_lease_id TEXT NOT NULL,
    new_process_lease_id TEXT NOT NULL,
    evidence_digest TEXT NOT NULL,
    transferred_at TEXT NOT NULL,
    CHECK (previous_owner_main_boot_id != new_owner_main_boot_id),
    CHECK (new_fence_revision = previous_fence_revision + 1),
    CHECK ((owner_ready_run_id IS NULL) != (owner_manual_compaction_id IS NULL)),
    UNIQUE(thread_binding_id, previous_fence_revision)
  );

CREATE TABLE codex_sidecar_process_leases (
    process_lease_id TEXT PRIMARY KEY,
    singleton_slot INTEGER NOT NULL CHECK (singleton_slot = 1),
    owner_main_boot_id TEXT NOT NULL,
    owner_main_pid INTEGER NOT NULL CHECK (owner_main_pid > 0),
    owner_main_process_start_identity TEXT NOT NULL,
    sidecar_spawn_instance_id TEXT NOT NULL UNIQUE,
    connection_epoch TEXT NOT NULL UNIQUE,
    runtime_manifest_digest TEXT NOT NULL,
    binary_sha256 TEXT NOT NULL,
    executable_path TEXT NOT NULL,
    isolated_state_dir TEXT NOT NULL,
    spawn_intent_at TEXT NOT NULL,
    spawn_visibility_deadline_at TEXT NOT NULL,
    pid INTEGER,
    process_group_id INTEGER,
    process_start_identity TEXT,
    ownership_confirmed_at TEXT,
    owner_main_dead_at TEXT,
    owner_main_death_evidence_digest TEXT,
    connection_opened_at TEXT,
    closed_at TEXT,
    tree_zero_at TEXT,
    tree_zero_matcher_mode TEXT CHECK (tree_zero_matcher_mode IN ('pre_cas', 'post_cas')),
    stable_zero_sample_transcript_digest TEXT,
    tree_zero_evidence_digest TEXT,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    CHECK (
      (pid IS NULL AND process_group_id IS NULL AND process_start_identity IS NULL
        AND ownership_confirmed_at IS NULL)
      OR
      (pid IS NOT NULL AND pid > 0 AND process_group_id IS NOT NULL AND process_group_id > 0
        AND process_start_identity IS NOT NULL AND ownership_confirmed_at IS NOT NULL)
    ),
    CHECK ((owner_main_dead_at IS NULL) = (owner_main_death_evidence_digest IS NULL)),
    CHECK (
      (tree_zero_at IS NULL AND tree_zero_matcher_mode IS NULL
        AND stable_zero_sample_transcript_digest IS NULL AND tree_zero_evidence_digest IS NULL)
      OR
      (tree_zero_at IS NOT NULL AND tree_zero_matcher_mode IS NOT NULL
        AND stable_zero_sample_transcript_digest IS NOT NULL AND tree_zero_evidence_digest IS NOT NULL)
    )
  );

CREATE TABLE codex_thread_resume_evidence (
    resume_evidence_id TEXT PRIMARY KEY,
    thread_binding_id TEXT NOT NULL,
    codex_thread_id TEXT NOT NULL,
    connection_epoch TEXT NOT NULL,
    pre_resume_thread_read_digest TEXT NOT NULL,
    resumed_thread_digest TEXT NOT NULL,
    evidence_digest TEXT NOT NULL UNIQUE,
    recorded_at TEXT NOT NULL,
    FOREIGN KEY (thread_binding_id)
      REFERENCES codex_thread_bindings(thread_binding_id),
    FOREIGN KEY (connection_epoch)
      REFERENCES codex_sidecar_process_leases(connection_epoch),
    UNIQUE(thread_binding_id, connection_epoch)
  );

CREATE TABLE ready_model_gateway_profile_snapshots (
          snapshot_ref TEXT PRIMARY KEY,
          snapshot_digest TEXT NOT NULL UNIQUE,
          profile_id TEXT NOT NULL,
          snapshot_json TEXT NOT NULL,
          credential_reference_id TEXT NOT NULL,
          created_at TEXT NOT NULL
        );

CREATE TABLE ready_model_gateway_request_receipts (
          receipt_id TEXT PRIMARY KEY,
          request_kind TEXT NOT NULL CHECK (request_kind IN (
            'product', 'automatic_compaction', 'manual_compaction'
          )),
          codex_thread_id TEXT NOT NULL,
          codex_turn_id TEXT NOT NULL,
          ready_run_id TEXT,
          manual_compaction_id TEXT,
          upstream_profile_snapshot_ref TEXT NOT NULL,
          upstream_profile_snapshot_digest TEXT NOT NULL,
          request_digest TEXT NOT NULL,
          accepted_at TEXT NOT NULL, budget_lane TEXT
          CHECK (budget_lane IS NULL OR budget_lane IN ('ordinary', 'delivery', 'final')),
          CHECK ((ready_run_id IS NULL) != (manual_compaction_id IS NULL)),
          CHECK (
            (request_kind IN ('product', 'automatic_compaction')
              AND ready_run_id IS NOT NULL AND manual_compaction_id IS NULL)
            OR
            (request_kind = 'manual_compaction'
              AND ready_run_id IS NULL AND manual_compaction_id IS NOT NULL)
          )
        );

CREATE TABLE codex_tool_group_admissions (
      gateway_request_receipt_id TEXT PRIMARY KEY,
      ready_run_id TEXT NOT NULL,
      codex_thread_id TEXT NOT NULL,
      codex_turn_id TEXT NOT NULL,
      tool_call_count INTEGER NOT NULL CHECK (tool_call_count > 0),
      parallel_group_charged INTEGER NOT NULL CHECK (
        parallel_group_charged = CASE WHEN tool_call_count >= 2 THEN 1 ELSE 0 END
      ),
      group_digest TEXT NOT NULL UNIQUE,
      admitted_at TEXT NOT NULL,
      FOREIGN KEY (gateway_request_receipt_id)
        REFERENCES ready_model_gateway_request_receipts(receipt_id),
      FOREIGN KEY (ready_run_id) REFERENCES codex_turn_bindings(ready_run_id)
    );

CREATE TABLE codex_tool_call_admissions (
      codex_thread_id TEXT NOT NULL,
      codex_turn_id TEXT NOT NULL,
      codex_call_id TEXT NOT NULL,
      gateway_request_receipt_id TEXT NOT NULL,
      ready_run_id TEXT NOT NULL,
      tool_name TEXT NOT NULL,
      args_digest TEXT NOT NULL,
      admitted_at TEXT NOT NULL,
      PRIMARY KEY (codex_thread_id, codex_turn_id, codex_call_id),
      FOREIGN KEY (gateway_request_receipt_id)
        REFERENCES codex_tool_group_admissions(gateway_request_receipt_id),
      FOREIGN KEY (ready_run_id) REFERENCES codex_turn_bindings(ready_run_id)
    );

CREATE TABLE ready_model_gateway_exchange_events (
      event_sequence INTEGER PRIMARY KEY AUTOINCREMENT,
      gateway_request_receipt_id TEXT NOT NULL,
      event_kind TEXT NOT NULL CHECK (event_kind IN ('request_admitted', 'response_completed')),
      instruction_digest TEXT,
      input_digest TEXT,
      input_items_json TEXT,
      input_total_string_characters INTEGER,
      input_max_string_characters INTEGER,
      tools_digest TEXT,
      tool_count INTEGER,
      body_bytes INTEGER,
      memory_history_redaction_digest TEXT,
      memory_history_redacted_item_count INTEGER,
      response_id TEXT,
      terminal_digest TEXT,
      output_digest TEXT,
      usage_digest TEXT,
      evidence_digest TEXT NOT NULL UNIQUE,
      recorded_at TEXT NOT NULL,
      FOREIGN KEY (gateway_request_receipt_id)
        REFERENCES ready_model_gateway_request_receipts(receipt_id),
      UNIQUE(gateway_request_receipt_id, event_kind),
      CHECK (
        (event_kind = 'request_admitted'
          AND instruction_digest IS NOT NULL
          AND input_digest IS NOT NULL
          AND input_items_json IS NOT NULL
          AND json_valid(input_items_json)
          AND json_type(input_items_json) = 'array'
          AND input_total_string_characters >= 0
          AND input_max_string_characters >= 0
          AND input_total_string_characters >= input_max_string_characters
          AND tools_digest IS NOT NULL
          AND tool_count >= 0
          AND body_bytes > 0
          AND memory_history_redaction_digest IS NOT NULL
          AND length(memory_history_redaction_digest) = 64
          AND memory_history_redaction_digest NOT GLOB '*[^0-9a-f]*'
          AND memory_history_redacted_item_count >= 0
          AND response_id IS NULL AND terminal_digest IS NULL
          AND output_digest IS NULL AND usage_digest IS NULL)
        OR
        (event_kind = 'response_completed'
          AND instruction_digest IS NULL AND input_digest IS NULL
          AND input_items_json IS NULL
          AND input_total_string_characters IS NULL
          AND input_max_string_characters IS NULL
          AND tools_digest IS NULL AND tool_count IS NULL AND body_bytes IS NULL
          AND memory_history_redaction_digest IS NULL
          AND memory_history_redacted_item_count IS NULL
          AND response_id IS NOT NULL AND terminal_digest IS NOT NULL
          AND output_digest IS NOT NULL AND usage_digest IS NOT NULL)
      )
    );

CREATE TABLE codex_manual_compaction_dispatch_attempts (
      attempt_id TEXT PRIMARY KEY,
      manual_compaction_id TEXT NOT NULL,
      connection_epoch TEXT NOT NULL,
      rpc_id INTEGER NOT NULL CHECK (rpc_id > 0),
      request_digest TEXT NOT NULL,
      dispatch_intent_at TEXT NOT NULL,
      child_write_attempted_at TEXT,
      child_write_confirmed_at TEXT,
      child_write_digest TEXT,
      unresolved_at TEXT,
      unresolved_reason TEXT CHECK (unresolved_reason IN (
        'response_timeout', 'child_write_error', 'connection_closed'
      )),
      response_kind TEXT CHECK (response_kind IN ('accepted', 'rejected')),
      response_digest TEXT,
      response_at TEXT,
      proven_absent_at TEXT,
      proven_absent_reason TEXT,
      proven_absent_evidence_digest TEXT,
      revision INTEGER NOT NULL CHECK (revision >= 1),
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (manual_compaction_id)
        REFERENCES codex_manual_compaction_bindings(manual_compaction_id),
      UNIQUE(connection_epoch, rpc_id),
      CHECK ((child_write_confirmed_at IS NULL) = (child_write_digest IS NULL)),
      CHECK ((unresolved_at IS NULL) = (unresolved_reason IS NULL)),
      CHECK ((response_kind IS NULL) = (response_digest IS NULL)),
      CHECK ((response_kind IS NULL) = (response_at IS NULL)),
      CHECK ((proven_absent_at IS NULL) = (proven_absent_reason IS NULL)),
      CHECK ((proven_absent_at IS NULL) = (proven_absent_evidence_digest IS NULL)),
      CHECK (child_write_confirmed_at IS NULL OR child_write_attempted_at IS NOT NULL)
    );

CREATE TABLE codex_browser_verifier_attempts (
      attempt_id TEXT PRIMARY KEY,
      ready_run_id TEXT NOT NULL UNIQUE,
      ready_task_id TEXT NOT NULL,
      ready_scope_id TEXT NOT NULL,
      ready_alias_id TEXT NOT NULL,
      alias_generation INTEGER NOT NULL CHECK (alias_generation >= 1),
      thread_binding_id TEXT NOT NULL,
      codex_thread_id TEXT NOT NULL,
      codex_turn_id TEXT NOT NULL,
      candidate_digest TEXT NOT NULL CHECK (
        length(candidate_digest) = 64 AND candidate_digest NOT GLOB '*[^0-9a-f]*'
      ),
      frozen_identity_digest TEXT NOT NULL CHECK (
        length(frozen_identity_digest) = 64 AND frozen_identity_digest NOT GLOB '*[^0-9a-f]*'
      ),
      upstream_profile_snapshot_ref TEXT NOT NULL,
      upstream_profile_snapshot_digest TEXT NOT NULL CHECK (
        length(upstream_profile_snapshot_digest) = 64
        AND upstream_profile_snapshot_digest NOT GLOB '*[^0-9a-f]*'
      ),
      workflow_closeout_seal_digest TEXT NOT NULL CHECK (
        length(workflow_closeout_seal_digest) = 64
        AND workflow_closeout_seal_digest NOT GLOB '*[^0-9a-f]*'
      ),
      status TEXT NOT NULL CHECK (status IN ('dispatching', 'settled')),
      outcome TEXT CHECK (outcome IN (
        'accept', 'repair', 'block', 'invalid', 'provider_unavailable', 'result_unknown', 'identity_drift'
      )),
      verdict_json TEXT,
      verdict_digest TEXT,
      sealed_candidate_digest TEXT,
      verification_usage_json TEXT,
      receipt_digest TEXT,
      dispatched_at TEXT NOT NULL,
      verified_at TEXT,
      settled_at TEXT,
      CHECK (
        (status = 'dispatching' AND outcome IS NULL AND verdict_json IS NULL
          AND verdict_digest IS NULL AND sealed_candidate_digest IS NULL
          AND verification_usage_json IS NULL AND receipt_digest IS NULL
          AND verified_at IS NULL AND settled_at IS NULL)
        OR
        (status = 'settled' AND outcome IS NOT NULL AND verdict_json IS NOT NULL
          AND verdict_digest IS NOT NULL
          AND verification_usage_json IS NOT NULL AND receipt_digest IS NOT NULL
          AND verified_at IS NOT NULL AND settled_at IS NOT NULL)
      ),
      FOREIGN KEY (ready_run_id) REFERENCES codex_turn_bindings(ready_run_id)
    );

CREATE TABLE codex_thread_archive_intents (
    archive_intent_id TEXT PRIMARY KEY,
    thread_binding_id TEXT NOT NULL UNIQUE,
    codex_thread_id TEXT NOT NULL UNIQUE,
    codex_session_id TEXT NOT NULL,
    isolated_thread_cwd TEXT NOT NULL,
    ready_conversation_alias TEXT NOT NULL,
    alias_generation INTEGER NOT NULL CHECK (alias_generation >= 1),
    source_kind TEXT NOT NULL CHECK (source_kind IN (
      'idle_close', 'engine_terminal_close', 'idle_reset', 'engine_terminal_reset',
      'engine_terminal_stop', 'browser_verifier_nonaccept', 'publication_divergence',
      'manual_compaction_quarantine', 'retired_backfill'
    )),
    retired_reason TEXT NOT NULL CHECK (retired_reason IN (
      'closed', 'user_reset', 'publication_diverged', 'manual_compaction_quarantine', 'cleanup'
    )),
    ready_run_id TEXT,
    retirement_evidence_digest TEXT NOT NULL,
    retirement_transaction_digest TEXT NOT NULL,
    intent_digest TEXT NOT NULL UNIQUE,
    state TEXT NOT NULL CHECK (state IN ('pending', 'result_unknown', 'acknowledged')),
    attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    last_attempt_at TEXT,
    last_attempt_connection_epoch TEXT,
    last_attempt_rpc_id INTEGER,
    last_error_code TEXT,
    last_absence_after_attempt_count INTEGER,
    last_absence_evidence_digest TEXT,
    last_absence_at TEXT,
    acknowledged_at TEXT,
    acknowledgement_kind TEXT CHECK (
      acknowledgement_kind IN ('rpc_success', 'archived_readback', 'archived_notification')
    ),
    acknowledgement_evidence_digest TEXT,
    revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
    requested_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (thread_binding_id) REFERENCES codex_thread_bindings(thread_binding_id),
    CHECK ((source_kind IN (
        'idle_close', 'idle_reset', 'manual_compaction_quarantine', 'retired_backfill'
      ) AND ready_run_id IS NULL)
      OR (source_kind IN (
        'engine_terminal_close', 'engine_terminal_reset', 'engine_terminal_stop',
        'browser_verifier_nonaccept', 'publication_divergence'
      ) AND ready_run_id IS NOT NULL)),
    CHECK (length(retirement_evidence_digest) = 64
      AND retirement_evidence_digest NOT GLOB '*[^0-9a-f]*'),
    CHECK (length(retirement_transaction_digest) = 64
      AND retirement_transaction_digest NOT GLOB '*[^0-9a-f]*'),
    CHECK (length(intent_digest) = 64 AND intent_digest NOT GLOB '*[^0-9a-f]*'),
    CHECK ((attempt_count = 0
        AND last_attempt_at IS NULL AND last_attempt_connection_epoch IS NULL
        AND last_attempt_rpc_id IS NULL)
      OR (attempt_count > 0
        AND last_attempt_at IS NOT NULL AND last_attempt_connection_epoch IS NOT NULL
        AND last_attempt_rpc_id IS NOT NULL AND last_attempt_rpc_id > 0)),
    CHECK ((last_absence_after_attempt_count IS NULL
        AND last_absence_evidence_digest IS NULL AND last_absence_at IS NULL)
      OR (last_absence_after_attempt_count IS NOT NULL
        AND last_absence_after_attempt_count >= 1
        AND last_absence_after_attempt_count <= attempt_count
        AND last_absence_evidence_digest IS NOT NULL
        AND length(last_absence_evidence_digest) = 64
        AND last_absence_evidence_digest NOT GLOB '*[^0-9a-f]*'
        AND last_absence_at IS NOT NULL)),
    CHECK (state != 'pending' OR attempt_count = 0
      OR last_absence_after_attempt_count = attempt_count),
    CHECK (state != 'result_unknown' OR attempt_count > 0),
    CHECK ((state != 'acknowledged'
        AND acknowledged_at IS NULL
        AND acknowledgement_kind IS NULL
        AND acknowledgement_evidence_digest IS NULL)
      OR (state = 'acknowledged'
        AND acknowledged_at IS NOT NULL
        AND acknowledgement_kind IS NOT NULL
        AND acknowledgement_evidence_digest IS NOT NULL
        AND length(acknowledgement_evidence_digest) = 64
        AND acknowledgement_evidence_digest NOT GLOB '*[^0-9a-f]*'))
  );

CREATE TABLE codex_thread_archive_attempts (
    archive_intent_id TEXT NOT NULL,
    attempt_count INTEGER NOT NULL CHECK (attempt_count >= 1),
    connection_epoch TEXT NOT NULL,
    rpc_id INTEGER NOT NULL CHECK (rpc_id > 0),
    request_digest TEXT NOT NULL,
    activated_at TEXT NOT NULL,
    child_write_attempted_at TEXT,
    child_write_confirmed_at TEXT,
    child_write_digest TEXT,
    unresolved_at TEXT,
    unresolved_reason TEXT CHECK (
      unresolved_reason IN ('response_timeout', 'child_write_error', 'connection_closed')
    ),
    response_kind TEXT CHECK (response_kind IN ('accepted', 'rejected')),
    response_digest TEXT,
    response_at TEXT,
    notification_digest TEXT,
    notification_at TEXT,
    revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
    PRIMARY KEY (archive_intent_id, attempt_count),
    UNIQUE (connection_epoch, rpc_id),
    FOREIGN KEY (archive_intent_id)
      REFERENCES codex_thread_archive_intents(archive_intent_id),
    CHECK (length(request_digest) = 64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
    CHECK ((child_write_confirmed_at IS NULL AND child_write_digest IS NULL)
      OR (child_write_confirmed_at IS NOT NULL
        AND child_write_digest IS NOT NULL
        AND length(child_write_digest) = 64
        AND child_write_digest NOT GLOB '*[^0-9a-f]*')),
    CHECK (child_write_confirmed_at IS NULL OR child_write_attempted_at IS NOT NULL),
    CHECK ((unresolved_at IS NULL AND unresolved_reason IS NULL)
      OR (unresolved_at IS NOT NULL AND unresolved_reason IS NOT NULL)),
    CHECK ((response_kind IS NULL AND response_digest IS NULL AND response_at IS NULL)
      OR (response_kind IS NOT NULL AND response_digest IS NOT NULL
        AND length(response_digest) = 64 AND response_digest NOT GLOB '*[^0-9a-f]*'
        AND response_at IS NOT NULL)),
    CHECK ((notification_digest IS NULL AND notification_at IS NULL)
      OR (notification_digest IS NOT NULL
        AND length(notification_digest) = 64
        AND notification_digest NOT GLOB '*[^0-9a-f]*'
        AND notification_at IS NOT NULL))
  );

CREATE TABLE ready_memory_sources (
      source_id TEXT PRIMARY KEY CHECK (length(trim(source_id)) > 0),
      conversation_id TEXT NOT NULL CHECK (length(trim(conversation_id)) > 0),
      source_digest TEXT NOT NULL UNIQUE CHECK (
        length(source_digest) = 64 AND source_digest NOT GLOB '*[^0-9a-f]*'
      ),
      source_updated_at TEXT NOT NULL CHECK (length(trim(source_updated_at)) > 0),
      evidence_refs_json TEXT NOT NULL DEFAULT '[]' CHECK (
        json_valid(evidence_refs_json)
        AND json_type(evidence_refs_json) = 'array'
        AND json_array_length(evidence_refs_json) <= 128
        AND length(evidence_refs_json) <= 32768
      ),
      summary_text TEXT,
      summary_digest TEXT CHECK (summary_digest IS NULL OR (
        length(summary_digest) = 64 AND summary_digest NOT GLOB '*[^0-9a-f]*'
      )),
      sealed_at TEXT,
      created_at TEXT NOT NULL CHECK (length(trim(created_at)) > 0),
      CHECK (
        (summary_text IS NULL AND summary_digest IS NULL AND sealed_at IS NULL)
        OR
        (summary_text IS NOT NULL AND length(trim(summary_text)) > 0
          AND length(summary_text) <= 65536
          AND summary_digest IS NOT NULL
          AND sealed_at IS NOT NULL AND length(trim(sealed_at)) > 0)
      )
    ) STRICT;

CREATE TABLE ready_memory_entries (
      entry_id TEXT PRIMARY KEY CHECK (length(trim(entry_id)) > 0),
      category TEXT NOT NULL CHECK (
        category IN ('preference', 'fact', 'project', 'workflow', 'other')
      ),
      content TEXT NOT NULL CHECK (length(trim(content)) > 0 AND length(content) <= 16384),
      content_digest TEXT NOT NULL CHECK (
        length(content_digest) = 64 AND content_digest NOT GLOB '*[^0-9a-f]*'
      ),
      origin TEXT NOT NULL CHECK (origin IN ('manual', 'consolidated')),
      confidence REAL NOT NULL CHECK (confidence >= 0.0 AND confidence <= 1.0),
      pinned INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)),
      status TEXT NOT NULL DEFAULT 'active' CHECK (
        status IN ('active', 'superseded', 'expired')
      ),
      superseded_by_entry_id TEXT,
      expires_at TEXT,
      source_refs_json TEXT NOT NULL DEFAULT '[]' CHECK (
        json_valid(source_refs_json)
        AND json_type(source_refs_json) = 'array'
        AND json_array_length(source_refs_json) <= 32
        AND length(source_refs_json) <= 8192
      ),
      state_revision INTEGER NOT NULL CHECK (state_revision >= 1),
      revocation_revision INTEGER NOT NULL CHECK (
        revocation_revision >= 0 AND revocation_revision <= state_revision
      ),
      last_used_at TEXT,
      created_at TEXT NOT NULL CHECK (length(trim(created_at)) > 0),
      updated_at TEXT NOT NULL CHECK (length(trim(updated_at)) > 0),
      CHECK (
        (status = 'superseded' AND superseded_by_entry_id IS NOT NULL
          AND length(trim(superseded_by_entry_id)) > 0
          AND superseded_by_entry_id <> entry_id)
        OR (status <> 'superseded' AND superseded_by_entry_id IS NULL)
      ),
      CHECK (status <> 'expired' OR expires_at IS NOT NULL),
      CHECK (pinned = 0 OR (status = 'active' AND expires_at IS NULL)),
      CHECK (origin = 'manual' OR json_array_length(source_refs_json) > 0)
    ) STRICT;

CREATE TABLE ready_memory_jobs (
      job_id TEXT PRIMARY KEY CHECK (length(trim(job_id)) > 0),
      job_kind TEXT NOT NULL CHECK (job_kind IN ('extraction', 'consolidation')),
      source_id TEXT,
      input_digest TEXT NOT NULL CHECK (
        length(input_digest) = 64 AND input_digest NOT GLOB '*[^0-9a-f]*'
      ),
      input_payload_json TEXT CHECK (input_payload_json IS NULL OR (
        json_valid(input_payload_json) AND json_type(input_payload_json) = 'object'
        AND length(input_payload_json) <= 65536
      )),
      status TEXT NOT NULL CHECK (
        status IN ('pending', 'leased', 'submitted', 'succeeded', 'no_output', 'failed', 'unknown')
      ),
      attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
      lease_owner TEXT,
      lease_token TEXT,
      lease_expires_at TEXT,
      provider_request_id TEXT,
      submitted_at TEXT,
      submission_receipt_json TEXT CHECK (
        submission_receipt_json IS NULL OR (
          json_valid(submission_receipt_json) AND json_type(submission_receipt_json) = 'object'
          AND length(submission_receipt_json) <= 131072
        )
      ),
      submission_receipt_digest TEXT CHECK (submission_receipt_digest IS NULL OR (
        length(submission_receipt_digest) = 64
        AND submission_receipt_digest NOT GLOB '*[^0-9a-f]*'
      )),
      terminal_at TEXT,
      result_receipt_json TEXT CHECK (
        result_receipt_json IS NULL OR (
          json_valid(result_receipt_json) AND json_type(result_receipt_json) = 'object'
          AND length(result_receipt_json) <= 65536
        )
      ),
      result_receipt_digest TEXT CHECK (result_receipt_digest IS NULL OR (
        length(result_receipt_digest) = 64
        AND result_receipt_digest NOT GLOB '*[^0-9a-f]*'
      )),
      effects_applied_at TEXT,
      last_error TEXT,
      created_at TEXT NOT NULL CHECK (length(trim(created_at)) > 0),
      updated_at TEXT NOT NULL CHECK (length(trim(updated_at)) > 0),
      FOREIGN KEY (source_id) REFERENCES ready_memory_sources(source_id) ON DELETE RESTRICT,
      UNIQUE (job_kind, input_digest),
      CHECK (
        (job_kind = 'extraction' AND source_id IS NOT NULL AND input_payload_json IS NULL)
        OR (job_kind = 'consolidation' AND source_id IS NULL AND input_payload_json IS NOT NULL)
      ),
      CHECK (effects_applied_at IS NULL OR status IN ('succeeded', 'no_output')),
      CHECK (
        (status = 'pending' AND lease_owner IS NULL AND lease_token IS NULL
          AND lease_expires_at IS NULL AND provider_request_id IS NULL
          AND submitted_at IS NULL AND submission_receipt_json IS NULL
          AND submission_receipt_digest IS NULL AND terminal_at IS NULL
          AND result_receipt_json IS NULL AND result_receipt_digest IS NULL
          AND last_error IS NULL)
        OR
        (status = 'leased' AND lease_owner IS NOT NULL AND lease_token IS NOT NULL
          AND lease_expires_at IS NOT NULL AND provider_request_id IS NULL
          AND submitted_at IS NULL AND submission_receipt_json IS NULL
          AND submission_receipt_digest IS NULL AND terminal_at IS NULL
          AND result_receipt_json IS NULL AND result_receipt_digest IS NULL
          AND last_error IS NULL)
        OR
        (status = 'submitted' AND lease_owner IS NULL AND lease_token IS NULL
          AND lease_expires_at IS NULL AND provider_request_id IS NOT NULL
          AND submitted_at IS NOT NULL AND submission_receipt_json IS NOT NULL
          AND submission_receipt_digest IS NOT NULL AND terminal_at IS NULL
          AND result_receipt_json IS NULL AND result_receipt_digest IS NULL
          AND last_error IS NULL)
        OR
        (status IN ('succeeded', 'no_output', 'failed', 'unknown')
          AND lease_owner IS NULL AND lease_token IS NULL AND lease_expires_at IS NULL
          AND provider_request_id IS NOT NULL AND submitted_at IS NOT NULL
          AND submission_receipt_json IS NOT NULL AND submission_receipt_digest IS NOT NULL
          AND terminal_at IS NOT NULL AND result_receipt_json IS NOT NULL
          AND result_receipt_digest IS NOT NULL
          AND ((status = 'failed' AND last_error IS NOT NULL)
            OR (status <> 'failed' AND last_error IS NULL)))
      )
    ) STRICT;

CREATE TABLE ready_memory_policies (
      policy_key TEXT PRIMARY KEY CHECK (length(trim(policy_key)) > 0),
      scope_kind TEXT NOT NULL CHECK (scope_kind IN ('global', 'conversation')),
      conversation_id TEXT,
      use_memories INTEGER CHECK (use_memories IS NULL OR use_memories IN (0, 1)),
      generate_memories INTEGER CHECK (generate_memories IS NULL OR generate_memories IN (0, 1)),
      contribute_to_memories INTEGER CHECK (
        contribute_to_memories IS NULL OR contribute_to_memories IN (0, 1)
      ),
      state_revision INTEGER NOT NULL CHECK (state_revision >= 1),
      revocation_revision INTEGER NOT NULL CHECK (
        revocation_revision >= 0 AND revocation_revision <= state_revision
      ),
      last_revocation_reason TEXT CHECK (
        last_revocation_reason IS NULL OR last_revocation_reason IN (
          'edit', 'delete', 'reset', 'use_off', 'generate_off', 'supersede', 'expire'
        )
      ),
      updated_at TEXT NOT NULL CHECK (length(trim(updated_at)) > 0),
      CHECK (
        (scope_kind = 'global' AND policy_key = 'global' AND conversation_id IS NULL
          AND use_memories IS NOT NULL AND generate_memories IS NOT NULL
          AND contribute_to_memories IS NULL)
        OR
        (scope_kind = 'conversation' AND conversation_id IS NOT NULL
          AND length(trim(conversation_id)) > 0
          AND policy_key = 'conversation:' || conversation_id
          AND use_memories IS NULL AND generate_memories IS NULL
          AND contribute_to_memories IS NOT NULL)
      ),
      CHECK (
        (revocation_revision = 0 AND last_revocation_reason IS NULL)
        OR (revocation_revision > 0 AND last_revocation_reason IS NOT NULL)
      )
    ) STRICT;

