CREATE TRIGGER codex_tool_request_rpc_binding_no_delete
  BEFORE DELETE ON codex_tool_request_rpc_bindings
  BEGIN SELECT RAISE(ABORT, 'codex_tool_request_rpc_binding_delete_forbidden'); END;

