      SELECT 1 FROM codex_tool_group_admissions g
       WHERE g.gateway_request_receipt_id = NEW.gateway_request_receipt_id
         AND g.ready_run_id = NEW.ready_run_id
         AND g.codex_thread_id = NEW.codex_thread_id
