  BEGIN SELECT RAISE(ABORT, 'codex_thread_archive_intent_identity_immutable'); END;

CREATE TRIGGER codex_thread_archive_ack_immutable
  BEFORE UPDATE ON codex_thread_archive_intents
  WHEN OLD.state = 'acknowledged' AND (
    NEW.state IS NOT OLD.state
    OR NEW.acknowledged_at IS NOT OLD.acknowledged_at
    OR NEW.acknowledgement_kind IS NOT OLD.acknowledgement_kind
    OR NEW.acknowledgement_evidence_digest IS NOT OLD.acknowledgement_evidence_digest
  )
  BEGIN SELECT RAISE(ABORT, 'codex_thread_archive_ack_immutable'); END;

CREATE TRIGGER codex_thread_archive_attempt_monotonic
  BEFORE UPDATE ON codex_thread_archive_intents
  WHEN NEW.attempt_count < OLD.attempt_count
  BEGIN SELECT RAISE(ABORT, 'codex_thread_archive_attempt_not_monotonic'); END;

CREATE TRIGGER chat_conversation_close_fields_insert_guard
    BEFORE INSERT ON chat_conversations
    WHEN NOT (
      (NEW.closed_at IS NULL AND NEW.closed_reason IS NULL
        AND NEW.close_evidence_digest IS NULL)
      OR
      (NEW.closed_at IS NOT NULL AND NEW.closed_reason = 'closed'
        AND length(NEW.close_evidence_digest) = 64
        AND NEW.close_evidence_digest NOT GLOB '*[^0-9a-f]*')
    )
    BEGIN SELECT RAISE(ABORT, 'chat_conversation_close_fields_invalid'); END;

CREATE TRIGGER chat_conversation_close_fields_update_guard
    BEFORE UPDATE ON chat_conversations
    WHEN NOT (
      (NEW.closed_at IS NULL AND NEW.closed_reason IS NULL
        AND NEW.close_evidence_digest IS NULL)
      OR
      (NEW.closed_at IS NOT NULL AND NEW.closed_reason = 'closed'
        AND length(NEW.close_evidence_digest) = 64
        AND NEW.close_evidence_digest NOT GLOB '*[^0-9a-f]*')
    )
    BEGIN SELECT RAISE(ABORT, 'chat_conversation_close_fields_invalid'); END;

CREATE TRIGGER chat_conversation_close_immutable
    BEFORE UPDATE ON chat_conversations
    WHEN OLD.closed_at IS NOT NULL
    BEGIN SELECT RAISE(ABORT, 'chat_conversation_close_immutable'); END;

CREATE TRIGGER chat_conversation_visibility_epoch_update_guard
    BEFORE UPDATE OF message_visibility_epoch ON chat_conversations
    WHEN NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch
      AND NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch + 1
    BEGIN SELECT RAISE(ABORT, 'chat_conversation_visibility_epoch_transition_invalid'); END;

CREATE TRIGGER chat_message_closed_scope_insert_guard
    BEFORE INSERT ON chat_messages
    WHEN EXISTS (
      SELECT 1 FROM chat_conversations scope
       WHERE scope.id = NEW.conversation_id AND scope.closed_at IS NOT NULL
    )
    BEGIN SELECT RAISE(ABORT, 'chat_message_closed_scope'); END;

CREATE TRIGGER chat_message_closed_scope_update_guard
    BEFORE UPDATE ON chat_messages
    WHEN EXISTS (
      SELECT 1 FROM chat_conversations scope
       WHERE scope.id IN (OLD.conversation_id, NEW.conversation_id)
         AND scope.closed_at IS NOT NULL
    )
    BEGIN SELECT RAISE(ABORT, 'chat_message_closed_scope'); END;

CREATE TRIGGER chat_message_visibility_epoch_insert_guard
    BEFORE INSERT ON chat_messages
    WHEN NOT EXISTS (
      SELECT 1 FROM chat_conversations scope
       WHERE scope.id = NEW.conversation_id
         AND scope.closed_at IS NULL
         AND scope.message_visibility_epoch = NEW.message_visibility_epoch
    )
    BEGIN SELECT RAISE(ABORT, 'chat_message_visibility_epoch_mismatch'); END;

CREATE TRIGGER chat_message_visibility_epoch_immutable
    BEFORE UPDATE OF message_visibility_epoch ON chat_messages
    WHEN OLD.message_visibility_epoch >= 0
      AND NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch
    BEGIN SELECT RAISE(ABORT, 'chat_message_visibility_epoch_immutable'); END;

CREATE TRIGGER codex_turn_message_visibility_epoch_immutable
    BEFORE UPDATE OF message_visibility_epoch ON codex_turn_bindings
    WHEN NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch
    BEGIN SELECT RAISE(ABORT, 'codex_turn_message_visibility_epoch_immutable'); END;

CREATE TRIGGER task_projection_visibility_epoch_insert_guard
    BEFORE INSERT ON task_projections
    WHEN NOT EXISTS (
      SELECT 1 FROM chat_conversations scope
       WHERE scope.id = NEW.scope_id
         AND scope.closed_at IS NULL
         AND scope.message_visibility_epoch = NEW.message_visibility_epoch
    )
    BEGIN SELECT RAISE(ABORT, 'task_projection_visibility_epoch_mismatch'); END;

CREATE TRIGGER task_projection_visibility_epoch_update_guard
    BEFORE UPDATE ON task_projections
    WHEN NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch
      OR NOT EXISTS (
        SELECT 1 FROM chat_conversations scope
         WHERE scope.id = OLD.scope_id
           AND scope.closed_at IS NULL
           AND scope.message_visibility_epoch = OLD.message_visibility_epoch
      )
    BEGIN SELECT RAISE(ABORT, 'task_projection_visibility_epoch_stale'); END;

CREATE TRIGGER run_meta_visibility_identity_immutable
      BEFORE UPDATE OF scope_id, message_visibility_epoch ON run_meta
      WHEN NEW.scope_id IS NOT OLD.scope_id
        OR NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch
      BEGIN SELECT RAISE(ABORT, 'run_meta_visibility_identity_immutable'); END;

CREATE TRIGGER run_meta_visibility_identity_insert_guard
      BEFORE INSERT ON run_meta
      WHEN NOT (
        (NEW.scope_id IS NULL AND NEW.message_visibility_epoch = -1)
        OR EXISTS (
          SELECT 1 FROM chat_conversations scope
           WHERE scope.id = NEW.scope_id
             AND scope.closed_at IS NULL
             AND scope.message_visibility_epoch = NEW.message_visibility_epoch
        )
      )
      BEGIN SELECT RAISE(ABORT, 'run_meta_visibility_identity_stale'); END;

CREATE TRIGGER pending_task_event_visibility_identity_immutable
      BEFORE UPDATE OF scope_id, message_visibility_epoch ON pending_task_events
      WHEN NEW.scope_id IS NOT OLD.scope_id
        OR NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch
      BEGIN SELECT RAISE(ABORT, 'pending_task_event_visibility_identity_immutable'); END;

CREATE TRIGGER skill_task_run_visibility_epoch_insert_guard
      BEFORE INSERT ON skill_task_runs
      WHEN NOT (
        (NEW.scope_id IS NULL AND NEW.message_visibility_epoch = -1)
        OR (
          NEW.scope_id IS NOT NULL
          AND NEW.message_visibility_epoch = -1
          AND NOT EXISTS (
            SELECT 1 FROM chat_conversations any_scope
             WHERE any_scope.id = NEW.scope_id
          )
        )
        OR EXISTS (
          SELECT 1 FROM chat_conversations scope
           WHERE scope.id = NEW.scope_id
             AND scope.closed_at IS NULL
             AND scope.message_visibility_epoch = NEW.message_visibility_epoch
        )
      )
      BEGIN SELECT RAISE(ABORT, 'skill_task_run_visibility_epoch_mismatch'); END;

CREATE TRIGGER skill_task_run_visibility_epoch_update_guard
      BEFORE UPDATE ON skill_task_runs
      WHEN NEW.scope_id IS NOT OLD.scope_id
        OR NEW.message_visibility_epoch IS NOT OLD.message_visibility_epoch
        OR NOT (
          (OLD.scope_id IS NULL AND OLD.message_visibility_epoch = -1)
          OR (
            OLD.scope_id IS NOT NULL
            AND OLD.message_visibility_epoch = -1
            AND NOT EXISTS (
              SELECT 1 FROM chat_conversations any_scope
               WHERE any_scope.id = OLD.scope_id
            )
          )
          OR EXISTS (
            SELECT 1 FROM chat_conversations scope
             WHERE scope.id = OLD.scope_id
               AND scope.closed_at IS NULL
               AND scope.message_visibility_epoch = OLD.message_visibility_epoch
          )
        )
      BEGIN SELECT RAISE(ABORT, 'skill_task_run_visibility_epoch_stale'); END;

CREATE TRIGGER chat_conversation_closed_delete_guard
    BEFORE DELETE ON chat_conversations
    WHEN OLD.closed_at IS NOT NULL
    BEGIN SELECT RAISE(ABORT, 'chat_conversation_closed_delete'); END;

CREATE TRIGGER chat_message_closed_scope_delete_guard
    BEFORE DELETE ON chat_messages
    WHEN EXISTS (
      SELECT 1 FROM chat_conversations scope
       WHERE scope.id = OLD.conversation_id AND scope.closed_at IS NOT NULL
    )
    BEGIN SELECT RAISE(ABORT, 'chat_message_closed_scope'); END;

CREATE TRIGGER ready_memory_source_identity_immutable
    BEFORE UPDATE ON ready_memory_sources
    WHEN NEW.source_id IS NOT OLD.source_id
      OR NEW.conversation_id IS NOT OLD.conversation_id
      OR NEW.source_digest IS NOT OLD.source_digest
      OR NEW.source_updated_at IS NOT OLD.source_updated_at
      OR NEW.evidence_refs_json IS NOT OLD.evidence_refs_json
      OR NEW.created_at IS NOT OLD.created_at
      OR (OLD.summary_digest IS NOT NULL AND (
        NEW.summary_text IS NOT OLD.summary_text
        OR NEW.summary_digest IS NOT OLD.summary_digest
        OR NEW.sealed_at IS NOT OLD.sealed_at
      ))
    BEGIN SELECT RAISE(ABORT, 'ready_memory_source_immutable'); END;

CREATE TRIGGER ready_memory_job_input_immutable
    BEFORE UPDATE ON ready_memory_jobs
    WHEN NEW.job_id IS NOT OLD.job_id
      OR NEW.job_kind IS NOT OLD.job_kind
      OR NEW.source_id IS NOT OLD.source_id
      OR NEW.input_digest IS NOT OLD.input_digest
      OR NEW.input_payload_json IS NOT OLD.input_payload_json
      OR NEW.created_at IS NOT OLD.created_at
    BEGIN SELECT RAISE(ABORT, 'ready_memory_job_input_immutable'); END;

CREATE TRIGGER ready_memory_policy_revision_monotonic
    BEFORE UPDATE ON ready_memory_policies
    WHEN NEW.state_revision <= OLD.state_revision
      OR NEW.revocation_revision < OLD.revocation_revision
    BEGIN SELECT RAISE(ABORT, 'ready_memory_policy_revision_not_monotonic'); END;

CREATE TRIGGER codex_turn_ready_memory_pair_insert
    BEFORE INSERT ON codex_turn_bindings
    WHEN NOT (
      (NEW.ready_memory_snapshot_json IS NULL
        AND NEW.ready_memory_snapshot_digest IS NULL
        AND NEW.ready_memory_state_revision IS NULL
        AND NEW.ready_memory_revocation_revision IS NULL
        AND NEW.ready_memory_read_receipt_json IS NULL
        AND NEW.ready_memory_read_receipt_digest IS NULL)
      OR
      (NEW.ready_memory_snapshot_json IS NOT NULL
        AND NEW.ready_memory_snapshot_digest IS NOT NULL
        AND NEW.ready_memory_state_revision IS NOT NULL
        AND NEW.ready_memory_revocation_revision IS NOT NULL
        AND NEW.ready_memory_revocation_revision <= NEW.ready_memory_state_revision
        AND ((NEW.ready_memory_read_receipt_json IS NULL
              AND NEW.ready_memory_read_receipt_digest IS NULL)
          OR (NEW.ready_memory_read_receipt_json IS NOT NULL
              AND NEW.ready_memory_read_receipt_digest IS NOT NULL)))
    )
    BEGIN SELECT RAISE(ABORT, 'codex_turn_ready_memory_pair_invalid'); END;

CREATE TRIGGER codex_turn_ready_memory_pair_update
    BEFORE UPDATE OF ready_memory_snapshot_json, ready_memory_snapshot_digest,
      ready_memory_state_revision, ready_memory_revocation_revision,
      ready_memory_read_receipt_json, ready_memory_read_receipt_digest
    ON codex_turn_bindings
    WHEN NOT (
      NEW.ready_memory_snapshot_json IS NOT NULL
      AND NEW.ready_memory_snapshot_digest IS NOT NULL
      AND NEW.ready_memory_state_revision IS NOT NULL
      AND NEW.ready_memory_revocation_revision IS NOT NULL
      AND NEW.ready_memory_revocation_revision <= NEW.ready_memory_state_revision
      AND ((NEW.ready_memory_read_receipt_json IS NULL
            AND NEW.ready_memory_read_receipt_digest IS NULL)
        OR (NEW.ready_memory_read_receipt_json IS NOT NULL
            AND NEW.ready_memory_read_receipt_digest IS NOT NULL))
    )
    BEGIN SELECT RAISE(ABORT, 'codex_turn_ready_memory_pair_invalid'); END;

CREATE TRIGGER codex_turn_ready_memory_snapshot_immutable
    BEFORE UPDATE OF ready_memory_snapshot_json, ready_memory_snapshot_digest,
      ready_memory_state_revision, ready_memory_revocation_revision
    ON codex_turn_bindings
    WHEN OLD.ready_memory_snapshot_digest IS NOT NULL AND (
      NEW.ready_memory_snapshot_json IS NOT OLD.ready_memory_snapshot_json
      OR NEW.ready_memory_snapshot_digest IS NOT OLD.ready_memory_snapshot_digest
      OR NEW.ready_memory_state_revision IS NOT OLD.ready_memory_state_revision
      OR NEW.ready_memory_revocation_revision IS NOT OLD.ready_memory_revocation_revision
    )
    BEGIN SELECT RAISE(ABORT, 'codex_turn_ready_memory_snapshot_immutable'); END;

CREATE TRIGGER codex_turn_ready_memory_receipt_immutable
    BEFORE UPDATE OF ready_memory_read_receipt_json, ready_memory_read_receipt_digest
    ON codex_turn_bindings
    WHEN OLD.ready_memory_read_receipt_digest IS NOT NULL AND (
      NEW.ready_memory_read_receipt_json IS NOT OLD.ready_memory_read_receipt_json
      OR NEW.ready_memory_read_receipt_digest IS NOT OLD.ready_memory_read_receipt_digest
    )
    BEGIN SELECT RAISE(ABORT, 'codex_turn_ready_memory_receipt_immutable'); END;

